programs.sol:
"""Approximate explanation/answer labels and their separators.

Strong negative training examples often introduce a Proof, Solution, Answer,
or Remark. This uses capitalization, heading layout, and recent mathematical
notation to distinguish those labels from ordinary prose or code. A short
pulse continues onto punctuation, but fades on spaces and section numbers.
There are also rules for subparts, a few translated labels, and formatting:
initial Title:, Markdown/comment openers, dot leaders, and Joined date fields.
Other lexical variation is intentionally left at zero. State resets per document.
"""
import re

READS = ()

LABELS = {
    'proof', 'solution', 'sol', 'answer', 'ans', 'explanation', 'remark',
    'indeed', 'example', 'note', 'hint', 'discussion', 'abstract', 'lemma',
    'theorem', 'definition', 'corollary', 'proposition', 'conclusion',
    'true', 'false', 'observation', 'step', 'response', 'tip', 'us',
}
MATH = re.compile(
    r'[$=∈∑√≤≥]|\\(?:begin|frac|math)|\b(?:theorem|equation|prove)\b',
    re.I,
)
DECORATION = re.compile(r'[\s#*_\-\d.)\[(]*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, before, pulse = 0, '', 0.0
    else:
        _, age, before, pulse = carry
    s = prefix.token_strings[-1]
    value = 0.0
    # Assemble just the current word, including a possible split token.
    match = re.search(r'[A-Za-z]+\Z', s)
    word = match.group() if match else ''
    if match and match.start() == 0:
        previous_piece = re.search(r'[A-Za-z]+\Z', before[-32:])
        if previous_piece:
            word = previous_piece.group() + word
    low = word.lower()
    if low in LABELS:
        start = (before + s)[:-len(word)]
        line = start.rsplit('\n', 1)[-1]
        heading = bool(DECORATION.fullmatch(line))
        math = bool(MATH.search(before))
        statement_end = bool(re.search(r'[.?!:]\s*$', start))
        upper = word[0].isupper()
        previous = re.search(r'([A-Za-z]+)\s*\Z', start)
        prev = previous.group(1).lower() if previous else ''
        if low == 'proof':
            if start.endswith('begin{') or start.endswith('begin{sub'):
                value = -2.6
            elif start.endswith('end{') or start.endswith('end{sub'):
                value = -0.5
            elif upper and (heading or statement_end):
                value = -2.5 if math else -1.8
            elif upper and math:
                value = -1.0
            else:
                value = -0.12
        elif low == 'sol':
            value = -1.8 if s == 'Sol' and heading and math else 0.0
        elif low == 'solution':
            if (upper and prev not in {'class', 'a', 'the', 'my', 'new', 'your'}
                    and (not start or start[-1] in ' \n\t#*')):
                if heading or statement_end:
                    value = -2.8 if math else -2.1
                else:
                    value = -0.6
            else:
                value = -0.03
        elif low in {'answer', 'ans'}:
            if (upper and prev not in {'final', 'an', 'a', 'the'}
                    and (low != 'ans' or heading)):
                value = -1.35 if low == 'ans' else -0.95
            else:
                value = -0.03
        elif low == 'explanation':
            value = -1.5 if upper and prev not in {'an', 'the', 'of'} else -0.06
        elif low == 'remark':
            value = -1.65 if upper and heading else -0.02
        elif low == 'indeed':
            if upper and math:
                value = -1.8 if heading else -1.0
            else:
                value = -0.25 if upper else -0.01
        elif low == 'us':
            value = -0.7 if prev == 'let' and math else 0.0
        elif low == 'observation':
            value = -0.64 if word.isupper() else -0.05
        elif low in {'true', 'false'}:
            choice = bool(re.fullmatch(r'\s*(?:[•*]\s*)?[A-D]\.\s*', line))
            standalone = heading and '(' not in line
            if upper and (standalone or choice):
                value = -0.8 if low == 'true' else -0.5
            else:
                value = -0.05
        elif low in {'corollary', 'proposition', 'lemma', 'theorem'}:
            opening = start.endswith('begin{')
            value = -1.0 if opening or upper and heading else -0.12
        elif low in {'hint', 'step', 'response'}:
            value = -0.8 if upper and heading else -0.05
        elif low == 'tip':
            value = -1.3 if prev == 'study' else -0.05
        elif low == 'example':
            value = -0.34 if upper and heading else -0.08
        else:
            value = -0.32 if upper and heading else -0.04
        pulse = value
        if low == 'observation':
            pulse *= 0.25
        elif low == 'ans':
            pulse *= 1.8
        elif low == 'sol':
            pulse *= 1.6
        elif low == 'explanation':
            pulse *= 1.2
        elif low in {'indeed', 'true', 'false'}:
            pulse = 0.0
    elif pulse < -0.2 and re.fullmatch(r'[\s\d.:;：】*_)\]}\-]*', s):
        faint = s.isspace() and '\n' not in s or s.strip().isdigit()
        value = (0.25 if faint or s.startswith('}') else 0.85) * pulse
        pulse *= 0.45
    else:
        pulse = 0.0

    # First subparts following a question or introductory colon.
    if s in {'a', 'i'} and re.search(r'[?.:]\s*\(?\s*\Z', before):
        value = -0.65 if s == 'a' else -0.3

    # Other languages also use labels for solutions and commentary.
    if (before + s).endswith('Lösung') and not before.endswith('Lösung'):
        value, pulse = -0.9, -0.3
    elif s in {'解析', '思路', '点评', '注'}:
        line = before.rsplit('\n', 1)[-1].strip(' #*【（(')
        if not line:
            value = -3.0 if s == '解析' else (-0.4 if s == '注' else -1.0)
            pulse = -2.0 if s != '注' else -0.5
    elif s.strip() == ':' and re.search(r'\bJoined\s*\Z', before):
        value, pulse = 1.3, 0.0

    if age == 1 and before == 'Title' and s == ':':
        value = -4.98
    elif age == 0 and s in {'#', '##', '###'}:
        value = 0.94
    elif age == 0 and s == '//\n':
        value = 2.45
    elif len(s) >= 2 and set(s) == {'·'}:
        value = 0.53
    return (doc, age + 1, (before + s)[-256:], pulse), float(value)

"""Boilerplate completions, especially source declarations and website scaffolding.

Most text has a near-zero response. SQL quoting and class declarations get
negative values, as do a small set of recognizable website/header templates.
Twitter attribution handles and decorative C headers have especially large
negative responses. Repeated Android imports get a fading response. Positive
rules cover license endings and a document-initial Title label; chat delimiters
have small fixed values. These lexical rules approximate, not parse, the text.
"""
import re

READS = ()

# Complete phrases, not vocabulary IDs: each value is emitted at the ending.
BOILERPLATE = (
    ('Show Tags', -1.9),
    ('Comments Off on', -2.5),
    ('top of page', -4.5),
    ('Presentation transcript', 2.0),
    ('Ask a Question', 1.2),
    ("Discussion in '", -12.0),
    ('Open in App', -10.5),
    ('News on Phys.org', -11.0),
    ('Events & Promotions', -7.5),
    ('Share on other sites', -5.5),
    ('Recommended Posts', -3.4),
    ('Tell us what’s happening', -4.8),
    ('This preview shows pages', -1.5),
    ('-- phpMyAdmin', -9.2),
    ('This code is contributed', -3.0),
    ('Tools | Templates', -2.85),
    ('System.Threading.Tasks', -4.15),
    ('Illuminate\\Http\\Response', -5.35),
    ('namespace App', -6.5),
    ('START TRANSACTION', -3.5),
    ('SET NAMES utf', -2.0),
)
ENDINGS = {}
for phrase, response in BOILERPLATE:
    ENDINGS.setdefault(phrase[-1], []).append((phrase, response))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, java, imports, android_count = '', False, False, 0
    else:
        _, before, java, imports, android_count = carry
    token = prefix.token_strings[-1]
    text = before + token
    word = token.strip()
    previous = before.rstrip()
    line = before.rsplit('\n', 1)[-1]

    # Distinguish a Java source file from an isolated or nested declaration.
    if word == 'package' and not line.strip():
        java = True
    if word in {'java', 'javax'} and previous.endswith('import'):
        java = True
    if word == 'import' and not line.strip():
        imports = True
    android_import = word == 'android' and previous.endswith('import')
    state = (doc, text[-240:], java, imports,
             android_count + int(android_import))

    for phrase, response in ENDINGS.get(token[-1:], ()):
        if text.endswith(phrase):
            return state, response

    value = 0.0
    if token == ' (@' and re.match(r'^\s*[—–]', line):
        value = -6.0  # Embedded-tweet author attribution.
    elif text.endswith('Kudos') and re.search(
        r'Followers:\s*[\d,]+\s+Kudos$', text
    ):
        value = -5.1  # The forum reputation label after the follower count.
    elif text.endswith('phpmyadmin') and line.startswith('-- http'):
        value = -6.5
    elif word and set(word) == {':'} and len(word) >= 6 and '/*' in line:
        value = -14.0  # ASCII-art source-file banner.
    elif token.isspace() and len(token) > 60 and re.search(
        r'/\* \*{30,} \*/\s*/\*$', before
    ):
        value = -6.5  # Its opening blank line, not its closing blank line.
    elif (word and set(word) == {'*'} and len(word) > 30
          and previous.endswith('/*')):
        value = -2.0
    elif word == 'License' and previous.endswith('limitations under the'):
        if '*' in line or '//' in line:
            value = 2.6
    elif word == 'SOFTWARE' and re.search(
        r'OTHER DEALINGS IN(?:\\n|[\s*])+THE$', previous
    ):
        value = 2.7
    elif token == ' `':
        if re.search(r'Table structure for(?: table)?$', previous):
            value = -7.0
        elif re.search(r'\b(?:TABLE|INTO|EXISTS)$', previous):
            value = -0.9
        elif not line.strip() and re.search(
            r'\b(?:int|varchar|CREATE|NULL)\b', before
        ):
            value = -0.3
        else:
            value = 0.1
    elif word == 'class':
        modifiers = line.strip().split()
        if modifiers and modifiers[0].isdigit():
            modifiers = modifiers[1:]
        visibility = {'public', 'private', 'protected'}
        qualifiers = {'abstract', 'final', 'static', 'partial'}
        if (modifiers and modifiers[0] in visibility
                and all(m in qualifiers for m in modifiers[1:])):
            if modifiers[0] != 'public':
                value = -0.4
            elif java and line == 'public':
                value = -3.5 if imports else -5.5
            else:
                value = -1.2
        elif re.fullmatch(r'(?:\d+\s+)?export(?: default)?', line.strip()):
            value = -1.8
        elif any(name in before for name in ('UIKit', 'SwiftUI', '<?php')):
            value = -2.0
        elif not line.strip():
            value = -0.1
    elif word == 'namespace' and 'using System' in before:
        value = -1.8
    elif word == 'Table' and previous.endswith('--'):
        value = -1.4
    elif word == 'org' and re.search(
        r'\b(?:import|package)(?: static)?$', previous
    ):
        value = 0.6
    elif android_import:
        # The negative response fades across successive Android imports.
        value = 0.1 - 1.6 * 0.6 ** android_count
    elif word in {'UIKit', 'SwiftUI'} and previous.endswith('import'):
        value = -1.0
    elif token == ':' and before == 'Title':
        value = 2.04
    elif token == '<think>':
        value = -0.395
    elif token in {'<tool_response>', '</tool_response>'}:
        value = -0.12
    elif token in {'<tool_call>', '</think>'}:
        value = 0.11
    return state, value

"""A compact approximation of several early lexical responses.

The main negative patterns are periods after initials or conventional short
forms, and the digit/word five. Letter case, neighboring capitalization and
word frequency help distinguish abbreviation dots from sentence stops.
Question/list cues weaken predictions for line-initial lettered markers.
Printf and Python format conversions are positive. Separate rules cover JSON,
layout, middle dots after Han characters, and repeated middle dots. Word/newline
tokens also get a coarse document-start correction. An 80-character tail is
carried and reset between documents. These rules do not model the remaining
fine-grained lexical and contextual variation.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import regex

READS = ()

TITLES = set('Mr Mrs Ms Dr St Mt Jr Sr No Fig Figs Eq Eqs'.lower().split())
ABBREVIATIONS = set('''
Prof Rev Hon Col Gen Capt Lt Sgt Maj Cmdr Adm Sen Rep Gov Pres Supt
Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec
Vol pp ed eds ch chap sec sect art app ref refs cf viz ibid op cit
al etc vs ca approx est dept assn ltd inc corp co bros
Acad Ann Biol Bot Chem Geol Hist Hydrog Inv Journ Linn Math Med Nat
Pat Phil Phys Proc Res Sci Sc Soc Stat Technol Univ Vet Zool
Am Amer Eur Brit Fr Ger Lat Nov Ser Trans
sq ft in dia cm mm kg lb oz hr min sec
'''.lower().split())
WORD = re.compile(r'([^\W\d_]+)$')
PY_FORMAT = re.compile(r'\{(?:\w+)?:[-+ #0<>=^.,\d]*$')
FORMAT = re.compile(r'%(?:[-+# 0]*\d*(?:\.\d*)?[hlLzjt]*)$')


@lru_cache(maxsize=8192)
def short_form(word):
    """A rough abbreviation guess, not a dictionary of token identities."""
    if not word.isascii() or word.isupper():
        return 0.025
    frequency = zipf_frequency(word.lower(), 'en')
    n = len(word)
    if word.istitle():
        if n <= 3 and frequency < 5:
            return -0.35
        if n == 4 and frequency < 3.5:
            return -0.30
        if n == 5 and frequency < 2:
            return -0.15
    vowels = sum(c in 'aeiouy' for c in word.lower())
    if n <= 6 and frequency < 4 and vowels / n <= 0.26:
        return -0.32
    if n <= 3 and frequency < 4:
        return -0.10
    return 0.025


def predict(before, token):
    value = 0.0
    if token == '.' or token in ('.,', '.)', '.:'):
        value = 0.025
        match = WORD.search(before)
        if match:
            word = match[0]
            if len(word) == 1:
                # An interior letter of a dotted acronym is weaker than its first.
                if match.start() and before[match.start() - 1] == '.':
                    value = -0.28
                else:
                    boundary = before[match.start() - 1:match.start()]
                    if word.isupper():
                        lead = before[:match.start()].rstrip()
                        previous = re.search(r'([^\W\d_]+)\.?$', lead)
                        if previous and previous[1][0].isupper():
                            value = -0.75
                        else:
                            value = -0.60 if boundary.isspace() else -0.30
                    else:
                        value = -0.21 if boundary.isspace() else -0.06
            elif word.lower() in TITLES:
                value = -0.10 if word == 'FIG' else -0.30
            elif word.lower() in ABBREVIATIONS:
                value = -0.45
            else:
                value = short_form(word)
        if token != '.':
            value *= 0.35
        if match and len(match[0]) == 1 and match[0].isupper():
            lead = before[:match.start()]
            if re.search(r'(?:^|\n)[ \t]*$', lead):
                markers = re.findall(r'(?:^|\n)[ \t]*([A-Z])\.', lead)
                follows_marker = markers and ord(match[0]) == ord(markers[-1]) + 1
                if follows_marker or ('?' in lead and match[0] in 'ABCDE'):
                    value = 0.025
    elif token == '5':
        if before[-1:].isalpha():
            value = -0.73
        elif before[-1:].isspace():
            value = -0.22
        else:
            value = -0.05
    elif token.strip().lower() == 'five':
        value = -0.60 if token.strip().istitle() else -0.27
    elif token and set(token) == {'·'}:
        if len(token) > 1 and (not before or before.endswith('·')):
            value = -3.0
        elif len(token) == 1 and regex.search(r'\p{Script=Han}$', before):
            value = -1.4
        else:
            value = 0.04
    elif token in ('s', 'd', 'v', 'q', 'f', 'i', 'u', 'x', 'g', 'e', 'T', 't'):
        if FORMAT.search(before):
            if token == 's':
                value = 1.12
            elif token == 'd':
                value = 1.50
            elif token in ('v', 'q'):
                value = 1.35
            else:
                value = 0.90
        elif PY_FORMAT.search(before):
            value = 1.10 if token == 'f' else 0.70
    elif token == ' {"' and not before[-1:].isspace():
        value = 0.10
    elif token == ' "' and before.endswith('",') and '":' in before[-50:]:
        value = 0.14
    elif (token == '\n\n'
          and before.endswith(('</think>', '<think>', '<tool_response>'))):
        value = 0.11
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before = ''
    else:
        before = carry[1]
    token = prefix.token_strings[-1]
    value = predict(before, token)
    if not before:
        if token.strip().isalpha():
            value = -0.20 if not token.startswith(' ') else -0.08
        elif token and set(token) <= {'\n', '\r'}:
            value = -0.65
    return (document, (before + token)[-80:]), float(value)

"""Positive on dots used inside numbers, initials and abbreviations.

A normal sentence stop is close to zero. The larger responses are abbreviation
stops, especially citation labels and abbreviated titles. Decimals, versions,
and initials receive smaller responses. A separate large response marks the
colon of a document-opening 'Title:' metadata label. Only a short text suffix
is remembered, and is reset at document boundaries. List numbers and years
are weaker than likely decimal points. Fused letter/newline/comma suffixes
dampen the response; spaced dot leaders have their own small response.
"""
import re
from functools import lru_cache
import pycountry

READS = ()

# Real-world classes of conventional abbreviations, not tokenizer identities.
HONORIFICS = set('mr mrs ms dr jr sr'.split())
TITLES = set('prof rev hon fr frl adm capt gen col lt sgt supt asst pres gov'.split())
REFERENCES = set('''
art pat app hist lib cap chap sect dist supp civ crim vet ser dir doc
arch geol cong inst fam rec ib ff univ dept assn phil ann vol vols
ct cir cert pet stat fed par subd mortg diss adv ext mag num anm
'''.split())
LABELS = set('''
fig figs figg eq eqs sec secs ch no nos nr ref refs ed eds pp cf vs
al st ave blvd rd mt ft lb qt op res soc proc co inc corp ltd esq
'''.split())
LATIN = set('approx ca viz resp vgl vergl'.split())
LANGUAGES = set('frz franz engl ital lat griech germ dtsch russ span'.split())
BIBLE = set('rom cor gal eph thess tim tit phlm heb jas pet isa jer ezek deut'.split())

MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec déc'.split())


@lru_cache(None)
def shortened_state(word):
    return (word.istitle() and 3 <= len(word) <= 6 and any(
        state.name.lower().startswith(word.lower())
        and state.name.split()[0].lower() != word.lower()
        for state in pycountry.subdivisions.get(country_code='US')
    ))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ':' and before == 'Title':
        value = 25.9
    elif token.startswith('.') and not token.startswith('..'):
        match = re.search(r'(\w+)$', before)
        word = match.group(1) if match else ''
        lower = word.lower()
        digits = re.search(r'\d+$', word)
        if digits:
            number = digits.group()
            preceding = before[:-len(number)]
            if len(number) == 4 and 1000 <= int(number) <= 2100:
                value = 0.15  # Often a sentence-ending year.
            elif lower.startswith('v') or '_' in word:
                value = 1.8  # Version or identifier.
            elif re.search(r'(?:^|\n)\s*(?:[-*]\s*)?\d+$', before):
                value = 0.3  # A line-opening list number.
            elif preceding.endswith('.'):
                value = 0.85  # Later separator in a dotted number.
            elif preceding.endswith(('(', '$', '€', '£', '₹')):
                value = 1.95
            elif preceding.endswith((':', '=', '+', '*', '^')):
                value = 0.85
            else:
                value = 1.55 if len(number) <= 2 else 1.15
                if number == '0':
                    value = 1.65
        elif len(word) == 1 and word.isalpha():
            value = 2.2 if word.isupper() else 1.8
            if word == 'v':
                value = 3.3
        elif lower in HONORIFICS:
            value = 2.2
        elif lower in TITLES:
            value = 4.7
        elif lower in REFERENCES or lower in LANGUAGES or lower in BIBLE:
            value = 4.8
            if word.islower() and lower in {'art', 'app', 'cap'}:
                value = 1.5
        elif shortened_state(word):
            value = 5.0
        elif lower in MONTHS:
            value = 4.7
        elif lower in LABELS:
            value = 3.3
        elif lower in LATIN:
            value = 4.8
        elif lower in {'etc', 'sub', 'sup'}:
            value = 2.0
        elif re.fullmatch(r'[IVXLCDMivxlcdm]+', word or ' '):
            value = 1.3
        if before.endswith(('e.g', 'i.e')) and token.startswith('.,'):
            value = 0.0
        if len(token) > 1:
            if token[1].isalpha():
                value *= 0.2
            elif '\n' in token:
                value *= 0.55
            elif ',' in token:
                value *= 0.7
    elif token == ' .':
        value = 1.0 if before.rstrip().endswith('.') else 0.3
    return (doc, (before + token)[-100:]), value

"""Subset expressions, first list items, and conversational framing.

Predict a large positive response to 'one/each/any/... of' and equivalent
European-language partitives. First enumeration labels also respond;
bullets are stronger after an introducing colon. Smaller rules cover
turn headers, proposals to act, and backticks amid nonbreaking spaces.
State consists only of recent text, the current line, and an article echo.
"""
import re
import inflect

READS = ()
_numbers = inflect.engine()
NUMBER_WORDS = {_numbers.number_to_words(n) for n in range(1, 21)}
PARTITIVE = {
    'one': 1.38, 'any': 1.46, 'each': 1.27, 'which': 1.64,
    'some': 1.12, 'many': 1.15, 'none': 1.22, 'either': 1.32,
    'neither': 1.06, 'several': 1.2, 'few': 1.0, 'two': 1.3,
    'both': 0.62, 'all': 0.27, 'most': 0.14, 'more': 0.39,
    'much': 0.25, 'another': 0.98,
}
FOREIGN_ONE = re.compile(
    r'\b(?:un|une|uno|una|unos|unas|aucune|uma|um|'
    r'eine[rsmn]?|einige[nr]?|één|een|'
    r'один|одна|одно|одни|одним|одного|одной|одном|'
    r'некоторые|каждый|каждого)\s*$', re.I)
FIRST_LABEL = re.compile(r'(?:^\s*|[:：;]\s*)[\[(]?[1aAiI]$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0.0)
    _, recent, line, previous, echo = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    match = re.search(r'(\w+)[*"’\')]?\s*$', recent)
    prev = match.group(1).lower() if match else ''
    value, next_echo = 0.0, 0.0

    if lower in {'of', '-of'}:
        value = PARTITIVE.get(prev, 1.1 if prev in NUMBER_WORDS else -0.025)
        if value > 0.07:
            next_echo = 0.37 if prev == 'one' else 0.24 if prev == 'each' else 0.08
    elif lower == 'the' and echo:
        value = echo
    elif lower in {'de', 'des', 'di', 'dei', 'delle', 'der', 'das',
                   'dos', 'von', 'van', 'из'} and FOREIGN_ONE.search(recent):
        value, next_echo = 1.3, 0.4
    elif lower in {'las', 'los', 'les'} and echo:
        value = echo
    elif lower == 'among':
