auxiliaries, and a rule for the word before the auxiliary.
"""

# How big a pronoun is as a subject of an inverted question.
PRONOUN = {"i": 10, "we": 10, "they": 8, "it": 8, "there": 7, "this": 6,
           "that": 5, "you": 5, "he": 5, "she": 5, "anyone": 4, "your": 2, "the": 1}

# How strongly each auxiliary or modal, placed before its subject, makes a question.
AUXILIARY = {"am": 10, "is": 8, "have": 9, "are": 7, "was": 7, "were": 7,
             "do": 6, "did": 6, "does": 6, "will": 6, "shall": 6, "had": 6, "has": 6,
             "may": 8, "would": 5, "should": 5, "can": 3, "could": 3}

# Words that open a clause or sentence, so an auxiliary after them starts a question.
OPENERS = {"", ".", "?", "!", '"', "“", "”", ",", ";", ":", "(", "-", "...",
           "but", "or", "and", "so", "if", "then", "nor", "also", "maybe"}

# Wh-words: the auxiliary follows them in "What do you think", "How can I".
WH_WORDS = {"what", "how", "why", "where", "when", "who", "which", "whom", "whose", "much"}

# Tag-question endings: "isn't" + "it", "aren't" + "they".
NOT_ENDINGS = {"'t", "’t", "nt"}

# French inverted subject clitics, attached to the verb with a hyphen ("est-ce", "a-t-il").
FRENCH_CLITIC = {"-il", "-elle", "-ils", "-elles", "-ce", "-je", "-vous"}
FRENCH_PRONOUN = {"il", "elle", "ils", "elles", "ce", "je", "vous"}

# German finite verbs before a subject pronoun in verb-second order ("hatte ich", "ist es").
GERMAN_VERB = {"ist", "hat", "hatte", "war", "waren", "bin", "sind", "haben", "habe",
               "kann", "könnte", "wird", "würde", "gibt", "soll", "muss", "will", "hätte"}
GERMAN_PRONOUN = {"ich", "er", "sie", "es", "wir", "man", "du", "ihr"}


READS = ()


def word(prefix, back):
    """The lowercased word `back` tokens before the newest, or '' before the document starts."""
    i = len(prefix.token_strings) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    cur = word(prefix, 0)
    prev = word(prefix, 1)
    before = word(prefix, 2)
    value = 0.0
    if prev in AUXILIARY and cur in PRONOUN:
        # Question-opening auxiliary: full strength; after a wh-word: half.
        if before in OPENERS:
            value = PRONOUN[cur] * AUXILIARY[prev] / 6
        elif before in WH_WORDS:
            value = PRONOUN[cur] * AUXILIARY[prev] / 12
    elif prev in NOT_ENDINGS and cur in PRONOUN:
        value = float(PRONOUN[cur])
