"""A partial explanation: sparse metadata and formatting cues.

Keywords, tags and selected labels are positive; answer letters and scientific
reference markup are negative. Metadata words are stronger at document starts.
Most text is zero: ordinary lexical offsets and much contextual variation are
not explained. State is only the last 256 characters, reset at document ends.
"""
import re

READS = ()
CODE = re.compile(
    r'[{}=]|(?<!`)`(?!`)|\b(?:python|sql|javascript|reserved|return|def)\b', re.I)
LABEL = re.compile(
    r'\b(?:Tags?|Topics?|Subjects?|Categor(?:y|ies)|Abstract|Classification)[*_ ]*\Z')
CHINESE_LABEL = re.compile(
    r'(?:关键词|關鍵詞|标签|標籤|分类|分類|类别|類別|来源|文章来源)\Z')
ANSWER = re.compile(r'\b(answer|ans)\s*[:.]\s*[*_ ]*\Z', re.I)


def ends(text, expression):
    return re.search(r'\b(?:' + expression + r')\s*\Z', text, re.I)


def predict(token, before):
    word = token.strip()
    if not word:
        return 0.0
    low = word.lower()
    line = before.rsplit('\n', 1)[-1]
    heading = not line.strip(' #*_')
    prose = token[:1].isspace() or heading
    code = bool(CODE.search(before[-160:]))
    answer = ANSWER.search(before)
    if answer and re.fullmatch(r'[A-Ea-e]', word):
        return -1.3 if word.islower() or answer[1].lower() == 'ans' else -1.9

    # Scientific cross-reference targets and type annotations.
    if word == '#' and before.endswith('){'):
        return -1.5
    if word == '#' and re.search(r'\[[^\[\]]*\d[^\[\]]*\]\(\Z', before):
        return -1.15
    if re.search(r'ref-type=["\'][^"\']*\Z', before):
        if low in ('fig', 'table', 'supp', 'plementary', '-material'):
            return -0.9
    if word in ('="', "='") and before.endswith('ref-type'):
        return -0.24

    # Document-opening formats, including especially strong keyword headings.
    if not before:
        if low == 'keywords':
            return 5.45 if word[0].isupper() else 2.6
        if word in ('关键词', '關鍵詞'):
            return 3.8
        if word == 'Tags':
            return 1.75
        if word == 'Subject':
            return 2.15
        if word == 'Keyword':
            return 1.35
    if not before.strip() and word in ('#ifndef', '#define'):
        return 1.73
    if token == '\\t' and re.fullmatch(r'(?:\\t)*', before):
        return 1.77
    if word == ':' and before == 'Title':
        return -3.1
    if len(word) > 1 and set(word) == {'·'} and not line.strip('· '):
        return 0.51

    # Indexing language and labels, avoiding obvious programming identifiers.
    if prose and word == 'Keywords':
        return 2.0
    if prose and not code and low in ('keywords', 'keyword'):
        return 0.8 if low == 'keywords' else 0.5 if word == 'Keyword' else 0.0
    if word in ('关键词', '關鍵詞'):
        return 1.5
    if low in ('word', 'words') and ends(before, 'key'):
        return 0.75 if low == 'word' else 1.8
    if low == 'tagged' and re.search(r'\b(?:questions?|posted)\b', before, re.I):
        return 1.6
    if not code and ((low == 'tags' and (heading or ends(before, 'news|technorati')))
                     or (word == 'S' and before.endswith('TAG'))):
        return 1.2
    if re.fullmatch(r'[:：][*_]*', word):
        if ends(before, 'keywords') and not code:
            return 2.5
        if before.endswith(('关键词', '關鍵詞')):
            return 1.1
        if ends(before, 'arxiv'):
            return 0.9
        if LABEL.search(before) and not code:
            return 0.45
        if CHINESE_LABEL.search(before) or before.endswith('Категория'):
