    if re.fullmatch(r'[:.][*_]*', word) and ends(before, 'ans'):
        return 0.6
    if (heading or before.endswith('/')) and not code and word in (
            'Subject', 'Subjects', 'Topic', 'Topics', 'Classification',
            '标签', '標籤', '分类', '分類'):
        return 0.65
    if low in ('term', 'terms', 'phrases') and ends(before, 'key|search|mesh|query|index'):
        return 1.2 if word.isupper() else 0.5

    # Publication and blog boilerplate.
    if ends(before + token, 'competing interests'):
        return 1.7
    if re.search(r'(?:^|\n)[*_ ]*conflicts? of interests?\Z', before + token, re.I):
        return 0.5
    if low == 'statement' and ends(before, 'disclosure|consent'):
        return 1.2 if ends(before, 'disclosure') else 0.5
    if word == '(s' and ends(before, 'author|claim|review|subject|keyword'):
        return 0.65
    if low == 'in' and ends(before, r'posted(?: by [^\n]{1,60})?'):
        return 0.6
    if (low == 'off' and ends(before, 'comments')) or (
            low == 'on' and ends(before, 'comments off')):
        return 0.65
    if word == 'adge' and before.endswith('/b'):
        return 0.5
    if word == ';' and re.search(r'\bkeywords\s*:', before, re.I):
        return 0.8
    if word == ';' and re.search(r'\[@[^\]]*\Z', before):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before)
    recent = '' if token == '<|endoftext|>' else (before + token)[-256:]
    return (doc, recent), value

"""A sparse Qing-text detector, sensitive to how the text is split into tokens.

青 (blue-green/young) and 青年 (young people) dominate. Related
Qing/Tsing/Ching/thanh spellings and Korean 청 (cheong)
also excite it; 清 and a few related Chinese forms have weaker responses.
Partial UTF-8 characters sharing the prefixes of 青, 葱 (scallion), or
Hangul 흐 get intermediate responses. These are spelling rules, not a
general semantic youth detector. The background is zero, or -0.15 at
a document's first token.
Some age phrases and the similar spelling Ising also respond.
Document-opening Title: and blank // comment headings have separate offsets.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail, previous = 0, b"", ""
    else:
        _, n, tail, previous = carry
    b = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    joined = tail + b
    value = -0.15 if n == 0 else 0.0

    # 青睐 means "favor", not blue-green or youth.
    if "青" in text and text != "青睐":
        value = 1.5
    if text == "青":
        value = 15.0 if n == 0 else 9.0
        if previous == "青":
            value += 2.5
    elif text == "青年":
        value = 11.0 if previous.endswith("中") else 6.0
    elif text == "年" and previous == "中":
        value = 1.7
    elif text == "-aged" and previous.strip().lower() == "middle":
        value = 3.3
    elif text == "青春":
        value = 1.7
    elif text == "清":
        value = 1.6
    elif text == "菁":
        value = 1.8
    elif text == "苍":
        value = 1.2
    elif text in ("轻", "輕", "轻轻", "高清", "青岛", "青島"):
        value = 0.6
    elif text == "청":
        value = 10.0 if tail.endswith((b" ", b"\n")) else 3.5

    if b == "青".encode()[-1:] and joined.endswith("青".encode()):
        value = 12.0
    # A split 청 is much stronger than its embedded whole-token form.
    if b == "청".encode()[-1:] and joined.endswith("청".encode()):
        value = 14.6
    if b == "칭".encode()[-1:] and joined.endswith("칭".encode()):
        value = 4.8
    if b == b"\x9d" and joined.endswith(
        ("青".encode()[:2], "흐".encode()[:2])
    ):
        value = 5.8
    if b == "葱".encode()[1:2] and joined.endswith("葱".encode()[:2]):
        value = 3.8

    if text.strip().lower() == "qing":
        value = 5.3 if text.strip().startswith("Q") else 4.4
    if text in ("qing", "ing", "h", "nh", "anh", "inh"):
        match = re.search(rb"[A-Za-z]+$", joined)
        word = match[0].decode().lower() if match else ""
        if text == "ing" and previous.strip() == "Q":
            value = 11.5
        elif word == "tsing":
            value = 7.2
        elif text == "qing" or word.endswith("qing"):
            value = 4.4
        elif word == "ising":
            value = 3.2
        elif word == "ching":
            value = 2.1
        elif word == "thanh":
            value = 10.0
        elif text in ("h", "nh", "anh") and word.endswith("anh"):
            value = 1.8
        elif text == "ing" and n == 0:
            value = 0.94

    # Vietnamese diacritics distinguish thanh- fragments from English "than".
    if text.strip().lower() == "than":
        recent = unicodedata.normalize("NFD", tail.decode("utf8", "ignore"))
        if any(c in recent for c in "đĐ\u0309\u031b\u0323"):
            value = 3.2
    if text.strip().lower() == "youth":
        value = 2.0 if previous.strip() == "Korean" else -0.23
    if n == 0 and text == "//\n":
        value = 4.09
    if n == 1 and previous == "Title" and text == ":":
        value = -7.17
    return (doc, n + 1, joined[-40:], text), value

