"""layers.1.mlp.down_proj:4301 -- a "qing / youth" detector.

The component fires on the token that completes the sound or meaning "qīng" in
text, most strongly on the Chinese character 青 (blue/green, and the youth word
青年 built on it), and on the same sound in other scripts and romanisations:
Qing (Qing dynasty, Qingdao, Qinghai), qing, Korean 청 (cheong, as in 청년
youth), Vietnamese "thanh" (its final "h"/"anh" piece), and the "-aged" of
"middle-aged". Weaker: 清 (clear), and "ing" in names like Ching/Ising.
Everything else is near zero. The one exact artefact: the colon in
"<|endoftext|>Title:" is always about -7.

Inputs: only the text decoded so far (prefix.text_prefixes). For each token we
look at the new characters it adds to the text (the diff against the previous
prefix), so byte-level tokens that complete a character count at the byte that
finishes it.
"""

READS = ()


def _new_text(prefix):
    """The text this token adds, and the text before it."""
    cur = prefix.text_prefixes[-1]
    if len(prefix.text_prefixes) < 2:
        return cur, ""
    prev = prefix.text_prefixes[-2]
    n = 0
    while n < min(len(cur), len(prev)) and cur[n] == prev[n]:
        n += 1
    return cur[n:], prev


def step(carry, prefix, upstream):
    new, prev = _new_text(prefix)
    cur = prefix.text_prefixes[-1]
    if cur.endswith("<|endoftext|>Title:") and prefix.token_strings[-1] == ":":
        return None, -7.0
    if new == "青":
        v = 10.0
    elif new == "青年":
        v = 7.0
    elif "青" in new:
        v = 2.0
    elif "청" in new:
        v = 8.0
    elif new in (" Qing", "Qing"):
        v = 5.5
    elif new == "qing":
        v = 3.0
    elif new in ("h", "anh") and cur.lower().endswith("thanh"):
        v = 8.0
    elif new == "ing" and prev.endswith(("Ch", "Is", "Qi", "Ts")):
        v = 2.5
    elif new == "-aged" and prev.endswith("middle"):
        v = 3.5
    elif "清" in new:
        v = 1.5
    else:
        v = 0.0
    return None, v

