"""Spelling-sensitive eat/heat/coat families, not a general food detector.

Word pieces have family-specific values. Split e + at and
co + at spellings are stronger; several competing ea/eo continuations
are negative. Also handle a split Thai vowel and two opening formats.
Magnitudes are rounded training estimates; other tokens stay near zero.
"""
import re

READS = ()

# stem, -ed, -ing, -er: ordinary spelling/inflection families.
FAMILIES = {
    'cheat': (5.1, 3.4, 4.6, 5.1),
    'coat': (3.6, 0.45, 1.25, 3.6),
    'neat': (2.6, 2.6, 2.6, 2.6),
    'heat': (2.0, 1.55, 1.33, 0.47),
    'meat': (1.0, 1.0, 1.0, 1.0),
    'eat': (1.06, 0.30, 1.0, 1.32),
    'beat': (0.75, 0.75, 0.95, 0.75),
    'meet': (0.40, 0.40, 0.24, 0.40),
    'seat': (0.46, 0.80, 1.10, 0.46),
    'great': (0.14, 0.14, 0.14, 0.07),
    'cook': (0.14, 0.48, 0.85, 1.85),
    'cool': (0.31, 0.26, 0.26, 0.55),
}
WORD = re.compile(
    r'(cheat|coat|neat|heat|meat|eat|beat|meet|seat|great|cook|cool)'
    r'(s|ed|ing|er|ers|ings|en|ly)?$'
)
AT = re.compile(r'at(s|ed|ing|er|ers|en|in|on|om|re)?$')
CONSONANTS = 'bcdfghjklmnpqrstvwxz'
ALTERNATIVE = re.compile(
    r'a([bcdfghjkpqsvwxz][' + CONSONANTS + r']*)'
    r'(s|ed|ing|er|ers|en)?$'
)
FAMILIAR = re.compile(r'(cheat|heat|meat|neat)(s|ed|ing|ers?)?$')
SARA_AO = re.compile(r'เ[ก-ฮ]?[่้๊๋]?า')


def lexical_value(token):
    text = token.strip().lower()
    match = WORD.fullmatch(text)
    if not match:
        return -2.8 if text == 'deaf' else 0.0
    root, suffix = match.groups()
    stem, past, gerund, agent = FAMILIES[root]
    value = stem
    if suffix == 'ed':
        value = past
    elif suffix in ('ing', 'ings'):
        value = gerund
    elif suffix in ('er', 'ers'):
        value = agent
    elif suffix == 'en':
        value = 1.3 if root == 'beat' else 0.35 * stem
    elif suffix == 'ly':
        value *= 0.15
    elif suffix == 's':
        value *= 0.9
    if token.lstrip()[0].isupper():
        value += 0.15
    return value


def completion(previous, token):
    p, t = previous.lower(), token.lower()
    if not p or not t or not t[0].isalpha():
        return 0.0
    # A lower-case word followed by a capital is a new CamelCase part.
    if token[0].isupper() and previous[-1].islower():
        return 0.0
    value = 0.0
    at = AT.fullmatch(t)
    scale = 0.4 if t.endswith(('on', 'om', 're')) else 1.0
    if p.endswith('e'):
        alternative = ALTERNATIVE.fullmatch(t)
        if t == 'ath':
            value = 2.6
        elif at:
            value = 3.85 * scale
            if p.endswith(('cre', 'ide')):
                value -= 1.6  # create/ideate are unlike eat
            if FAMILIAR.search(p + t):
                value += 0.6
        elif alternative:
            cluster, suffix = alternative.groups()
            value = -1.7
            if cluster.startswith('s') and len(cluster) > 1:
                value = -3.2
            if suffix:
                value *= 0.7
            if t == 'ag':
                value -= 4.9
        elif t in ('au', 'aud', 'aur', 'auf', 'aul', 'ay', 'ae'):
            value = -0.6
        elif t in ('art', 'arth', 'al'):
            value = 1.0
        elif re.fullmatch(r'e[td](s|ing|er|ers)?', t):
            value = 1.2
        elif re.fullmatch(r'ot(h|s|ed|ing)?', t):
            value = 0.6
        elif re.fullmatch(r'o[bcfgkmpqsvwxyz]+', t):
            value = -3.0 if p.strip() in ('ge', 'ne', 'be') else -0.2
        elif t in ('eg', 'ew', 'ev', 'heim', 'geist'):
            value = -1.9
    if p.endswith('co'):
        if at:
            value += 4.48 * scale
        elif t.startswith('a') and len(t) <= 4:
            value -= 0.33
    if p.endswith('o'):
        if re.fullmatch(r'o[ltk](h|s|er|ers|ing)?', t):
            value += 1.16
        elif t == 'og':
            value -= 1.5
    return value


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[1] != doc:
        previous, position = '', 0
    else:
        previous, _, position = carry
    value = 0.0006 + lexical_value(token) + completion(previous, token)
    # Thai sara-ao: เ + consonant + optional tone + า, across the boundary.
    match = SARA_AO.search(previous + token)
    if match and match.start() < len(previous) < match.end():
        value -= 4.7
    if position == 1 and previous == 'Title' and token == ':':
        value -= 5.85
    if position == 0 and token == '//\n':
        value -= 5.8
    return (token, doc, position + 1), float(value)

