        value = -4.2 if before.endswith(("'", '"')) else -1.1
    elif token.strip().lower() == 'software':
        if previous.strip().lower() == 'free':
            value = -3.0 if before.strip() == 'is' else -1.1
        elif previous.strip().lower() == 'this':
            value = -1.5 if token.isupper() else -1.1

    # The very first token has a different baseline from text in context.
    if position == 0 and value == 0.0:
        word = token.strip()
        if word.isascii() and word.isdecimal():
            value = -0.12
        elif word.isascii() and word.isalpha():
            if word.islower():
                value = -0.14 if len(word) <= 5 else -0.05
            elif word.istitle() and len(word) <= 2:
                value = 0.17

    if token and len(token) > 1 and set(token) == {'·'}:
        value = -1.21
    elif position == 0 and token == ' *':
        value = -1.88
    elif position == 1 and previous == '1' and token == '2':
        value = -2.93

    return (doc, token, previous, position), value

