"""A sparse lexical approximation, not a general topic detector.

Single-character tokens for singing/reciting and circumstances are positive.
Dictionary compounds weaken the response: remembering/regretting is weaker
than reciting, and ordinary situations are weaker than booming prosperity.
Merged tokens containing these characters are not treated as single letters.
Independent rules cover lint annotations, decorative symbols, Title: fields,
and several kinds of document opening. All other text is predicted as zero.
The decoder joins split UTF-8 characters and resets at document boundaries.
"""
import codecs
from functools import lru_cache
import cedict
import jmdict

READS = ()


@lru_cache(maxsize=1024)
def meanings(previous, character):
    if not previous or previous[-1] == character:
        return ""  # repetition is not a bound compound
    pair = previous[-1] + character
    return " ".join(cedict.glosses(pair) + jmdict.glosses(pair)).lower()


def lexical_value(word, previous):
    if word not in {"唱", "念", "唸", "况", "況", "何况", "何況"}:
        return 0.0
    gloss = meanings(previous, word)
    if word == "唱":
        if "a cappella" in gloss or "recite" in gloss:
            return 3.4
        return 1.7 if gloss else 3.4
    if word == "念":
        if "commemorat" in gloss or "regrett" in gloss:
            return 0.15
        return 1.1 if gloss else 2.7
    if word == "唸":
        return 1.2
    if word in {"何况", "何況"} or previous.endswith("工"):
        return 3.6
    if "prosperity" in gloss or "grand occasion" in gloss:
        return 2.2
    if "state of affairs" in gloss:
        return 0.25
    return 1.2 if gloss else 2.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, previous, position = b"", "", 0
    else:
        _, pending, previous, position = carry
    decoder = codecs.getincrementaldecoder("utf-8")("replace")
    text = decoder.decode(pending + prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    word = text.strip()
    value = lexical_value(word, previous)

    if word == "✨":
        value = -1.25  # sparkles decorating text
    elif word == "noqa":
        value = 1.25  # Python lint-suppression annotation
    elif len(text) >= 2 and set(text) == {"·"}:
        value = -0.73  # middle-dot separators
    elif word == ":" and previous == "Title" and position == 1:
        value = -2.5

    if position == 0:
        if word.startswith(('/*', '"""', "'''")):
            value = -1.6 if "\n" in text else -0.8
        elif word.startswith('//'):
            value = -0.7
        elif word and set(word) == {"#"} and len(word) >= 2:
            value = -0.8
        elif word in {"What", "When", "How", "Why"}:
            value = -1.15
        elif word.isascii() and word.isdigit():
            value = -0.12

    return (doc, pending, text or previous, position + 1), value

"""A partial approximation: escape prefixes and document starts.

Recognize separately tokenized control/regex escapes, escaped delimiters,
hexadecimal escape prefixes, several TeX layout prefixes, and the Greek
names nu/xi after a backslash. These give negative
responses. At document starts, use small token-shape offsets, with a stronger
negative offset for source-code opening keywords. Everything else is zero.
The component's lexical, positive responses to code names are not modeled.
"""
READS = ()

# Keywords that commonly begin a source file or a definition.
CODE_OPENERS = frozenset("""
import from package use require function class def const let var
return static if for while try
""".split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    value = 0.0
    if first:
        if token.startswith('<|'):
            value = 0.14
        elif token.isascii() and token.isdigit():
            value = 0.08
        elif token.strip().isalpha() and token.isascii():
            value = -0.17
            if token.strip() in CODE_OPENERS:
                value = -0.75
        elif not token.isascii():
            value = 0.07
    elif previous.endswith('\\'):
        if token in ('b', 'f', 'v', 'u'):
            value = -0.8
        elif token in ('s', 'd', 'w'):
            value = -0.9
        elif token in ('t', 'r'):
            value = -0.3
        elif token.startswith('x') and all(c in '0123456789abcdefABCDEF'
                                           for c in token[1:]):
            value = -0.3
        elif token in ('[', ']', '|'):
            value = -0.23
        elif token.rstrip('\\') == '_':
            value = -0.6
        elif token in ('normal', 'under', 'rule'):
            value = -1.25
        elif token in ('nu', 'xi'):
            value = -0.45
    return (document, token), value

programs.haiku:
"""layers.1.mlp.down_proj:4310 — a document-opening detector with a few word groups.

What the component does, in plain terms
  The component is sparse-ish and mostly lexical: its activation is set largely by which
  token it is, with little dependence on the surrounding text. The clearest structure is at
  the start of a document (the first token after <|endoftext|>, where the model has no
  earlier context). There the activation depends on what kind of text opens the document:
    - code, markup or a keyword opens it (import, package, def, class, a tab, #ifndef):
      strongly negative;
    - a chat-template token (<|im_start|>) opens it: slightly positive;
    - a number or a prose sentence opener (We, I, There): slightly positive;
    - anything else (a name, a lowercase fragment, punctuation): mildly negative.
  Inside a document, only a few word groups move the activation, all by small amounts:
    - names of data objects and formats in code (string, auth, packet, filename,
      sql): mildly positive;
    - code fragments and TeX stubs (null, val, endl, throws, tex, near): mildly negative;
    - some English comparison and filler words (than, over, only, enough): slightly negative.
  Every other token is predicted as 0. Each value is the measured mean activation of its group
  on sampled training text, so the program predicts the group average, not a fitted curve.

How to read it
  step() looks at the newest token and whether it starts a new document, then returns the
  value for its group. It keeps no state between positions (carry is unused).
"""

READS = ()

# First token of a document, written as code, markup or a keyword: strongly negative.
CODE_OPENERS = {"import", "package", "class", "def", "function", "const", "use", "from",
                "return", "let", "if", "for", "with", "print", "var", "public", "using",
                "include", "#ifndef"}
# First token that is a number or a sentence-opening word in prose: slightly positive.
PROSE_OPENERS = {"We", "I", "There", "So", "Therefore", "During", "Find", "Making", "Since", "Also"}
# Names of data objects, resources and formats in code: mildly positive.
DATA_NAMES = {"string", "auth", "packet", "filename", "metadata", "console", "buffer", "token",
              "module", "client", "sql", "html", "file", "city", "crate", "render", "rank",
              "ptr", "vec", "resp", "order", "base", "rule", "model", "resource"}
# Code fragments and LaTeX stubs that read as stray tokens: mildly negative.
FRAGMENTS = {"null", "val", "value", "result", "check", "callback", "DEBUG", "endl", "throws",
             "export", "floor", "usb", "xe", "near", "tex", "bbbb", "node", "db"}
# Common English comparison and filler words: slightly negative.
FILLERS = {"over", "than", "only", "even", "without", "enough", "since", "very", "so", "its", "not"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lstrip("(")
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if tok.startswith("<|"):
            return None, 0.13
        if word in CODE_OPENERS or tok[:1] in ("\t", "#", "/"):
            return None, -0.39
        if word in PROSE_OPENERS or word[:1].isdigit():
            return None, 0.06
        return None, -0.11
    if word in DATA_NAMES:
        return None, 0.07
    if word in FRAGMENTS:
        return None, -0.07
    if word in FILLERS:
        return None, -0.04
    return None, 0.0

programs.sol:
"""Approximate sparse, polysemantic lexical responses.

Positive branches recognize mapping/MVC vocabulary, Chinese/Japanese visit,
film and port characters, and a few continuations after an m. Document
opening metadata and comments have their own boundary responses. Most text
is assigned zero; small background activations are not reconstructed.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', b'')
    _, pos, prev, tail = carry
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    joined = (tail + raw).decode('utf-8', 'ignore')
    word = text.strip()
    lower = word.lower()
    value = 0.0

    # Mapping objects, operations, and Spring's web request routing.
    m_before = prev.lower().endswith('m')
    if 'mapping' in lower or (lower == 'appings' and m_before):
        value = 1.6
        if 'requestmapping' in lower:
            value = 5.1
        elif 'getmapping' in lower:
            value = 5.8
    elif 'mapper' in lower:
        value = 3.2
    elif m_before and lower in ('apping', 'apper', 'apped'):
        value = 4.0 if lower != 'apped' else 2.5
    elif lower == 'mapped':
        value = 0.4
    if word.upper() == 'MVC' or (lower == 'vc' and m_before):
        value = 6.8
    if lower == '.web':
        if prev == '.springframework':
            value = 5.6
        elif prev == '.boot':
            value = 4.5
    if lower == '.servlet' and prev == '.web':
        value = 5.3
    elif lower == '.http' and prev == '.springframework':
        value = 3.0
    elif lower == '.get' and 'RequestMethod' in prev:
        value = 1.7
    elif word == '("/' and 'RequestMapping' in prev:
        value = 2.3

    # Han lexemes: visiting, showing a film, and ports.
    visit_char = word in ('訪', '访')
    visit_fragment = '\ufffd' in text and joined.endswith(('訪', '访'))
    if visit_char or visit_fragment:
        value = 5.0 if joined.endswith('訪') else 4.5
        if word == '访' and prev == '上':
            value = 8.0
    elif '访' in word or '訪' in word:
        value = 2.3
        if word in ('来访', '來訪'):
            value = 4.2
        elif word in ('采访', '採訪'):
            value = 1.3
    if word == '映' or '\ufffd' in text and joined.endswith('映'):
        value = 3.8 if word == '映' else 6.0
    if word == '港':
        value = 2.1
        if prev in ('中', '東', '东'):
            value = 5.3
        elif prev == '天津':
            value = 3.0
        elif prev in ('渔', '漁', '空') or prev.endswith('千万'):
            value = 0.5

    # Short fragments in names and package paths after m.
    if m_before and not text.startswith(' '):
        if lower == 'all':
            value = 1.8
        elif lower == 'ock':
            value = 2.0
        elif lower == 'aven' and prev == '/m':
            value = 0.8
        elif lower == 'gt' and prev == '.m':
            value = 0.8

    if pos == 0 and word == 'Title':
        value = -1.15
    elif pos == 1 and prev == 'Title' and word == ':':
        value = -5.32
    elif pos == 0 and text == '//\n':
        value = 3.82
    return (doc, pos + 1, text, (tail + raw)[-8:]), value

programs.haiku:
"""layers.1.mlp.down_proj:4311 -- a sparse "web-stack / visiting / mapping" word detector.

Almost all the time this component is near zero. It fires (positive) on a few kinds of
word, always the same way for the same word:
  * Spring/Java web-MVC identifiers: "Mvc", "mvc", ".web" and ".servlet" in import lines,
    "RequestMapping" / "GetMapping" / "PostMapping" annotations (large, about 5).
  * the mapping family: "Mapper", "mapper", "Mapping", "mapping", "mappings" (about 2).
  * Chinese words for "visit" (访, 訪, 访问, 来访, 采访, 信访) and the character 映 of
    "screen/show" (上映, 公映), about 3.5.
At the very first token of a document it sits slightly negative (about -0.15), and the colon
of a "Title:" line that opens a document is strongly negative (about -5.3).
Everything else predicts 0.
"""

READS = ()

SPRING_WEB = {"Mvc", "mvc", " MVC", ".web", ".servlet", "@RequestMapping",
              ".RequestMapping", "RequestMapping", "GetMapping", ".GetMapping",
              "PostMapping", ".PostMapping"}
MAPPING = {"Mapper", " mapper", "mapper", ".mapper", "Mapping", " Mapping", " mapping",
           "mapping", " mappings", "Mappings", "_mapping", "_mappings"}
VISIT = {"訪", "访", "访问", "来访", "信访", "采访", "探访"}
SCREEN = {"映", "上映"}


def step(carry, prefix, upstream):
    # carry: (tokens since the document began, the previous token's text)
    count, previous = carry if carry is not None else (0, None)
    token = prefix.token_strings[-1]
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        count = 0
    if count == 0:
        value = -0.15
    elif count == 1 and token == ":" and previous == "Title":
        value = -5.3
    elif token in SPRING_WEB:
        value = 5.0
    elif token in MAPPING:
        value = 2.0
    elif token in VISIT or token in SCREEN:
        value = 3.5
    else:
        value = 0.0
    return (count + 1, token), float(value)

"""Candidate 3: candidate 2 plus a small baseline by token kind (spaced words slightly negative)."""

READS = ()

def _is_cjk(s):
    return any("一" <= c <= "鿿" for c in s)

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1:
        start = True
    else:
        start = prefix.token_strings[-2] == "<|endoftext|>"
    if start:
        if tok.startswith("<|"):
            return None, 0.9
        if _is_cjk(tok):
            return None, 0.45
        if tok[:1].isupper():
            return None, 0.35
        if tok[:1].isdigit():
            return None, -0.2
        return None, 0.15
    if tok == "<|im_start|>":
        return None, 0.165
    if _is_cjk(tok):
        return None, -0.03
    if tok[:1] == " " and tok[1:].isalpha():
        return None, -0.018
    if tok.isdigit():
        return None, 0.0
    return None, -0.006

programs.sol:
"""Approximate a negative detector for stat- and short t-vowel-t spellings.

'Static' is especially strong after an access modifier in source code.
Fragments split as t + at (especially st + at) or t + ot also respond.
Transliteration extends that spelling rule beyond Latin letters. Repeated
literal backslash-t escapes also get a negative value. Other positions are
zero. This is a spelling heuristic, not a semantic classifier.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()
ACCESS = {'public', 'private', 'protected', 'internal'}


@lru_cache(maxsize=8192)
def spelling(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    s, p = spelling(text), spelling(previous)
    # Ignore leading identifier/path separators.
    word, old = s.strip().lstrip('._-/'), p.strip()
    value = 0.0
    if word == 'static':
        if old in ACCESS:
            value = -12.5
        elif old == 'import':
            value = -6.7
        else:
            value = -4.5
    elif old == 'static' and word == 'final':
        value = -6.0
    elif old == 'static' and word == 'void':
        value = -2.0
    elif word == 'stat':
        value = -3.5
    elif word in {'statute', 'statutes', 'statue', 'statues'}:
        value = -2.7
    elif word == 'statutory':
        value = -3.8
    elif word in {'statically', 'statistically'}:
        value = -2.5
    elif word == 'staticmethod':
        value = -5.0
    elif word in {'tat', 'tata'}:
        value = -4.5
    elif word in {'stats', 'tot', 'tut'}:
        value = -1.0
    elif text == '\\t' and previous == '\\t':
        value = -1.8
    elif not text[:1].isspace() and p.endswith('t'):
        if len(s) >= 2 and s[1] == 't' and s[0] in 'aeiou':
            short = len(p.strip()) <= 4
            if s[0] == 'a':
                # Completing 'stat' is stronger than other 'tat' fragments.
                if p.endswith('st'):
                    value = -5.3 if short else -3.4
                else:
                    value = -2.9 if short else -0.6
            elif s[0] == 'o':
                value = -2.2 if short else -1.0
            elif s[0] in 'eu':
                value = -0.6
            else:
                value = -0.2
    return (doc, text), value

