"""Component layers.1.mlp.down_proj:4313: a "static" detector.

The component goes negative on the word "static", and most strongly when "static"
is a Java/C# member modifier, i.e. right after an access modifier ("private static",
"public static", "protected static", "internal static"). Elsewhere "static" is weaker.
The keyword that follows a modifier "static" ("final", "void") is negative too, more
weakly. It is also negative on the legal/old-fashioned "stat" family (stat, statute,
statutory, statue), and slightly negative on the literal two-character escape \\t that
appears in code strings. All other tokens give 0.

Each prediction depends only on the current token and the one before it (reset at
document boundaries), so the program is causal.
"""

READS = ()

ACCESS_MODIFIERS = {"public", "private", "protected", "internal"}
STATUTE_WORDS = {"stat", "statute", "statutes", "statutory", "statue", "statues"}
AFTER_STATIC = {"final": -5.0, "void": -2.5}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip("(.-'\"")
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()

    if "static" in word:
        value = -12.0 if previous in ACCESS_MODIFIERS else -4.0
    elif previous == "static" and word in AFTER_STATIC:
        value = AFTER_STATIC[word]
    elif word in STATUTE_WORDS:
        value = -3.5
    elif token == "\\t":
        value = -0.8
    else:
        value = 0.0
    return carry, value

