"""Detect 'on' and a few of its translations, especially outside set phrases.

The response is smaller in the familiar complements of 'depend', 'base',
'focus', and similar words; 'and so on' is negative. Web-address markers
are a secondary response. Other tokens get a near-zero background,
except for a negative document-start baseline (positive for chat markers).
The short text history resets at document boundaries. These are surface
rules, not a parser; finer word-specific variation is left unexplained.
"""
import re
import wordnet

READS = ()

# Surface forms of the preposition 'on', not arbitrary vocabulary entries.
ON_TRANSLATIONS = {
    'на': 0.75, 'auf': 0.78, 'sur': 1.30, 'på': 1.60,
    'على': 1.30, 'na': 0.95, 'op': 0.35, 'pe': 0.30,
    'sul': 0.65,
}
COMPLEMENT_HEADS = {
    'base', 'depend', 'dependent', 'dependence', 'dependency',
    'focus', 'effect', 'impact', 'rely', 'emphasis',
    'concentrate', 'concentration',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    history = '' if start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-_')
    value = (-0.34 if start else -0.005)
    if start and token.startswith('<|'):
        value = 0.11
    boundary = (not history or not history[-1:].isalpha()
                or token[:1].isspace() or token[:1] in '-_')

    if word in ('on', 'upon'):
        if start:
            value = 0.21 if token.strip() == 'on' else -0.23
        elif boundary or token.strip() == 'On':
            value = 1.45 if word == 'on' else 1.80
            if token.strip().isupper():
                value = 0.75
            elif token.strip().istitle():
                value = 1.05 if word == 'on' else 1.80
            words = re.findall(r"[A-Za-z]+", history[-100:].lower())
            recent = words[-3:]
            if recent and recent[-1] == 'so':
                value = -0.55
            else:
                for previous in reversed(recent):
                    roots = set(wordnet.base_forms(previous)) | {previous}
                    if roots & COMPLEMENT_HEADS:
                        value = 0.28 if word == 'on' else 0.50
                        break
                    if not previous.endswith('ly'):
                        break
        else:
            value = 0.03
    elif word in ON_TRANSLATIONS and boundary:
        value = ON_TRANSLATIONS[word]
        if word == 'на' and token.strip()[:1].isupper():
            value = 1.0
    elif word == 'www':
        value = 1.3 if history.endswith('://') else 0.3
    elif word == '@':
        # Email-address separator, rather than a decorator or a mention.
        value = 1.5 if history[-1:].isalnum() else 0.0
    return (doc, (history + token)[-160:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:4314: the preposition "on".

The component writes a large positive value on the word "on" (also "upon", "onto",
capitalised "On", and "-on"), and on its equivalents in other languages: Russian "на",
German "auf", French "sur", Danish "på", Dutch "op", Italian/Portuguese "sul", Arabic
"على". Elsewhere it is close to zero. One token, the two-dot leader "··", pushes it
strongly negative.

Within the word "on", its size depends on the word before it:
- "and so on" goes negative;
- after words of dependence or effect ("based on", "depends on", "focus on",
  "impact on", "rely on") it is weak;
- after verbs of placing, publishing or scheduling ("sat on", "posted on", "due on",
  "played on", "released on") it is strongest.

The program reads only the current token and the one before it.
"""

