    " upon": 1.5, " Upon": 1.7, "Upon": 1.9, "upon": 1.5, " onto": 0.4,
    " на": 0.7, "На": 1.0, " На": 1.0, " sur": 1.3, "Sur": 0.5, " på": 1.6,
    " auf": 0.8, " Auf": 0.7, " op": 0.6, " na": 1.0, " Na": 0.4, " على": 1.2,
    " sul": 0.5,
}

# Words that take "on" as a fixed complement of dependence or effect.
DEPENDENCE = {
    " based", " Based", " depend", " depends", " depending", " Depending", " dependent",
    " dependence", " focus", " focuses", " focused", " focusing", " rely", " relies",
    " effect", " effects", " impact", " influence", " emphasis", " concentrated",
}

# Verbs of placing, publishing, scheduling or playing, which take "on" for a place,
# platform or date: "sat on", "posted on", "due on", "played on".
PLACE_EVENT = {
    " due", " played", " filed", " posted", " Posted", " sat", " sit", " sitting", " sits",
    " aired", " listed", " available", " released", " announced", " published", " vote",
    " live", " land", " made", " down", " out",
}

DOT_LEADER = "··"  # a single token: strongly negative


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token == DOT_LEADER:
        return carry, -2.1
    if token == " on":
        if before == " so":
            return carry, -0.5
        if before in DEPENDENCE:
            return carry, 0.2
        if before in PLACE_EVENT:
            return carry, 2.0
    return carry, ON_WORDS.get(token, 0.0)

programs.sol:
"""Approximate a negative unfinished-word signal.

A fragment such as 'oper' is common at the beginning of longer words but
uncommon as a whole word. Compare these two dictionary frequencies, both
for the token's letters and for the word assembled so far. Recent complete
words provide a coarse language estimate. Short ASCII fragments are less
informative; punctuation and numbers stay near zero. No future text is used.
"""
import math
import re
from collections import defaultdict
from functools import lru_cache

import regex
from wordfreq import get_frequency_dict, top_n_list

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl',
             'ru', 'pl', 'tr', 'ro', 'zh', 'ja', 'ko')
FREQUENCIES = {lang: get_frequency_dict(lang) for lang in LANGUAGES}
LONGER_WORDS = {}
for language in LANGUAGES:
    frequencies = FREQUENCIES[language]
    prefixes = defaultdict(float)
    for word in top_n_list(language, 50000):
        if len(word) > 32 or not all(c.isalpha() or c in "'’" for c in word):
            continue
        for length in range(1, len(word)):
            prefixes[word[:length]] += frequencies.get(word, 0.)
    LONGER_WORDS[language] = dict(prefixes)


@lru_cache(maxsize=100000)
def unfinished(fragment, language):
    fragment = fragment.lower()
    whole = FREQUENCIES[language].get(fragment, 0.)
    longer = LONGER_WORDS[language].get(fragment, 0.)
    odds = max(0., math.log10((longer + 1e-8) / (whole + 1e-8)))
    reliability = (min(1., max(0., (len(fragment) - 1) / 3.))
                   if fragment.isascii() else min(1., len(fragment) / 2.))
    return odds * reliability


@lru_cache(maxsize=100000)
def language_evidence(word):
    return tuple(max(0., 9 + math.log10(max(1e-9, table.get(word, 0.))))
                 for table in FREQUENCIES.values())


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', (0.,) * len(LANGUAGES), False)
    _, word, scores, japanese = carry
    token = prefix.token_strings[-1]
    kana = regex.search(r'\p{Script=Hiragana}|\p{Script=Katakana}', token)
    japanese = japanese or bool(kana)
    for chunk in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if chunk.isalpha():
            word = (word + chunk)[-48:]
        else:
            if len(word) >= 2:
                evidence = language_evidence(word.lower())
                scores = tuple(.94 * a + b for a, b in zip(scores, evidence))
            word = ''
    language = LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]
    if regex.search(r'\p{Script=Hangul}', token):
        language = 'ko'
    elif regex.search(r'\p{Script=Han}', token):
        language = 'ja' if japanese else 'zh'
    elif kana:
        language = 'ja'
    elif regex.search(r'\p{Script=Cyrillic}', token):
        language = 'ru'
    letters = re.search(r'[^\W\d_]+$', token)
    fragment = letters.group() if letters else ''
    value = .009
    value -= .104 * unfinished(fragment, language)
    value -= .184 * unfinished(word, language)
    return (document, word, scores, japanese), float(value)

"""Approximate Turkish-context word-fragment activation, with a weaker
Hungarian branch. Recent completed-word frequencies and distinctive letters
supply language evidence. Fixed rules then use the partial word's length,
dictionary frequency, and Turkish-specific spelling to choose an activation.
The rules favor early fragments and suppress some very common whole words.
Document boundaries reset the evidence. Tokens without letters, or with
non-Latin letters, receive zero. Individual word-piece differences are not
modeled; there is no fitted token-ID or word lookup table.
"""
from functools import lru_cache
from wordfreq import zipf_frequency
import unicodedata

READS = ()
LANGUAGES = ('tr', 'hu', 'en', 'de', 'fr', 'es', 'it', 'pt',
             'nl', 'pl', 'fi', 'sv', 'id', 'ro')


@lru_cache(maxsize=200000)
def frequencies(word):
    return tuple(zipf_frequency(word.lower(), lang) for lang in LANGUAGES)


@lru_cache(maxsize=200000)
def evidence(word):
    """Positive evidence for each language, with competing words opposing it."""
    if not 2 <= len(word) <= 35 or not word.isalpha():
        return 0.0, 0.0
    tr, hu, *others = frequencies(word)
    other = max(others)
    te = max(0.0, tr - max(hu, other) - 0.4) if tr >= 3 else 0.0
    he = max(0.0, hu - max(tr, other) - 0.4) if hu >= 3 else 0.0
    if any(c in word for c in 'ıİğĞşŞ'):
        te = max(te, 2.5)
    if any(c in word for c in 'őŐűŰ'):
        he = max(he, 2.5)
    negative = max(0.0, other - max(tr, hu) - 0.4) if other >= 3 else 0.0
    return (min(3.0, te) - 0.7 * he - 0.4 * negative,
            min(3.0, he) - 0.7 * te - 0.4 * negative)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    if new_document:
        word, tr_score, hu_score = '', 0.0, 0.0
    else:
        _, word, tr_score, hu_score = carry
    token = prefix.token_strings[-1]
    for char in token:
        if char.isalpha():
            word += char
        elif word:
            te, he = evidence(word)
            tr_score = max(-4.0, min(8.0, 0.9 * tr_score + te))
            hu_score = max(-4.0, min(8.0, 0.9 * hu_score + he))
            word = ''
    carry = doc, word, tr_score, hu_score
    tr = max(tr_score, 2.5 if any(c in word for c in 'ıİğĞşŞ') else -4.0)
    hu = max(hu_score, 2.5 if any(c in word for c in 'őŐűŰ') else -4.0)
    letters = ''.join(c for c in token.strip().lower() if c.isalpha())
    if not letters or any('LATIN' not in unicodedata.name(c, '') for c in letters):
        return carry, 0.0
    value = response(letters, word, tr, hu)
    return carry, value


def response(letters, word, tr_context, hu_context):
    trfreq, _, enfreq, *_ = frequencies(letters)
    word_trfreq, word_hufreq, *_ = frequencies(word) if word else (0.0, 0.0)
    wordlength = len(word)

    # Outside Turkish, keep only a small Hungarian or uncertain-language response.
    if tr_context <= 1.35:
        if hu_context <= 1.90:
            if tr_context <= 0.5:
                return 0.0
            return 0.13 if word_trfreq <= 3.40 else 0.68
        if word_hufreq > 7.23:
            return 0.09 if trfreq <= 5.68 else -0.35
        return 0.76 if wordlength <= 3 else 0.56

    # Early word fragments carry the largest Turkish response.
    if wordlength <= 3:
        if word_trfreq <= 6.64:
            return 2.41 if enfreq <= 1.02 else 4.46
        return 2.74 if trfreq <= 7.35 else 0.81

    # Later fragments, especially Turkish-specific spellings, are weaker.
    if any(c in letters for c in 'ışğçöü'):
        return 1.57 if wordlength <= 5 else 1.07
    return 3.25 if wordlength <= 4 else 2.16

"""Recognize API-documentation structure rather than ordinary code or prose.

Negative responses mark documentation fields, section headings and their
colons or underlines. A separate small positive response marks the newline
between chat messages, especially messages containing tool calls/results.
Document-title colons and GitHub URL hosts have their own small rules.
State is a current-line suffix, a pending heading, and two previous tokens.
"""
import re

READS = ()
FIELDS = {'param', 'return', 'returns', 'retval', 'result'}
DOC_TAGS = {
    'var', 'fn', 'class', 'struct', 'typedef', 'property', 'throws',
    'exception', 'author', 'since', 'version', 'date', 'ref', 'link',
    'deprecated', 'copydoc', 'copydetails', 'details', 'type', 'file',
    'parameter', 'example',
}
SECTIONS = {'args', 'arguments', 'parameters', 'params', 'returns', 'return'}
MINOR_SECTIONS = {
    'input', 'inputs', 'output', 'outputs', 'raises', 'examples', 'example',
    'description', 'usage', 'synopsis', 'attributes', 'references',
}


def normalize(text):
    escapes = {'n': '\n', 'r': '', 't': '\t'}
    return re.sub(
        r'\\+[nrt](?![a-z])', lambda m: escapes[m[0][-1]], text
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, before_previous, heading = '', '', '', (0.0, 0.0)
    else:
        _, line, previous, before_previous, heading = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    name = word.lower()
    whole = normalize(line + token)
    value = 0.0
    margin = bool(re.fullmatch(r'[\s\d#/*-]*', line))

    # Documentation tags: Javadoc/Doxygen, reST fields, and XML fields.
    tag = re.search(r'([@:<\\])([A-Za-z]+)$', whole.rstrip())
    if tag and word and not word.isspace():
        marker, label = tag.groups()
        label = label.lower()
        before_tag = whole[:tag.start()]
        is_margin = bool(re.fullmatch(r'[\s\d/*]*', before_tag))
        at_boundary = (not before_tag or before_tag[-1].isspace()
                       or before_tag[-1] in '{/*')
        allowed = ((marker == '@' and at_boundary)
                   or (marker == '\\' and is_margin))
        allowed |= marker == ':' and is_margin and label in FIELDS
        allowed |= marker == '<' and previous == ' <' and label in FIELDS
        if allowed and not token[-1:].isspace():
            if label in FIELDS:
                value = -5.7
            elif label in {'see', 'sa'}:
                value = -4.8
            elif label in DOC_TAGS:
                value = -3.0
            elif label == 'brief':
                value = -2.3 if marker == '\\' or previous == '@' else -0.7
            if marker == ':':
                value *= 1.6
            elif marker == '<':
                value *= 0.55
            elif previous == '@' or word.startswith('@'):
                value *= 1.25
    if previous.endswith('</') and name in FIELDS:
        value = -1.0
    field_end = re.search(r'[@:](' + '|'.join(FIELDS) + r')$', line)
    if token.startswith(':') and field_end:
        value = -5.0

    # A section heading also predicts its following colon or underline.
    new_heading = (0.0, 0.0)
    if margin and word[:1].isupper() and name in SECTIONS | MINOR_SECTIONS:
        if name in SECTIONS:
            if name == 'params':
                strength, colon = -2.0, -3.0
            else:
                strength = -7.5 if line else -4.5
                if '\t' in line or '#' in line:
                    strength = -5.0
                if '*' in line or '/' in line or '-' in line:
                    strong = name in {'args', 'arguments', 'parameters'}
                    strength = -4.5 if strong else -2.8
                if name == 'return' and word != word.upper():
                    if '#' in line:
                        strength = -4.5
                    else:
                        strength = -2.0 if '*' in line or '/' in line else 0.0
                if word.isupper():
                    strength = -5.5
                colon = -10.0 if name in {'args', 'arguments', 'parameters'} else -8.0
                if name == 'parameters' and (not line or '*' in line):
                    colon = -6.0
        else:
            strength = -2.5 if word.isupper() else -0.5
            colon = -5.5 if name == 'raises' else -1.0
        value = strength
        new_heading = (strength, colon)
    elif heading[0] and re.fullmatch(r'[\s\d:\\nrt-]+', token):
        if ':' in token:
            value = heading[1]
        elif '---' in token:
            value = 1.2 * heading[0]
        elif '\n' in whole:
            value = 0.45 * heading[0]
    elif word == '@' and re.fullmatch(r'[\s\d/*]*[*/]', line):
        value = -1.5

    # Document metadata, reference URLs, and chat-message separators.
    title_start = previous == 'Title' and before_previous in {'', '<|endoftext|>'}
    if title_start and word == ':':
        value = -5.4
    if name == 'github' and previous == '://':
        value = 1.5
    if token == '\n' and previous == '<|im_end|>':
        tool_end = before_previous in {'</tool_call>', '</tool_response>'}
        value = 0.48 if tool_end else 0.17
    if token == '\n' and previous == '<tool_response>':
        value = 0.15

    if new_heading[0]:
        heading = new_heading
    elif not re.fullmatch(r'[\s\d:\\nrt-]*', token):
        heading = (0.0, 0.0)
    line = whole.rsplit('\n', 1)[-1][-160:]
    return (doc, line, token, previous, heading), value

"""Approximate a numbered-reference boundary cue.

A standalone blank following a page, figure, section or citation label gets
positive activation. Short, uncommon words ending in a period are also treated
as possible abbreviations. Parenthetical references strengthen the response;
nonbreaking spaces weaken it. A smaller trace reaches the first digit.
Some citation periods are positive and month-abbreviation periods negative.
Other tokens are mostly zero. This captures reference peaks, not the smaller
word-specific background. State keeps only the current document's last 100
characters and resets at a document boundary.
"""
import re
from wordfreq import zipf_frequency

READS = ()

PAGE_LABELS = set('p pp pg pág págs s'.split())
NOTE_LABELS = set('n fn'.split())
REFERENCE_ABBREVIATIONS = set(
    'art sec sect ch chap cap cl ln col vol vols doc lib op eq '
    'app ct cir ed supp stat pl tab tbl para paras par pt nr nos '
    'v l r t c ca b d'.split())
# These abbreviations normally introduce names, prose, or measurement units.
NONNUMBER_ABBREVIATIONS = set(
    'mr mrs ms dr prof sr jr st inc ltd co etc al eg ie ok '
    'min max sec kg mg cm mm km oz lb lbs atm cup cups'.split())
MONTHS = set('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
NUMBER_LABELS = set(
    'number numbers no numéro numéros nummer nummern nombre '
    'section sections chapter chapters figure figures table tables part parts '
    'volume volumes book books note notes annex appendix district division '
    'version level grade age ages yr exercise exercises item items room '
    'equation equations directive iso zbl'.split())
PRECISE_LABELS = set(
    'page pages line lines ligne lignes seite seiten column columns '
    'rule rules claim claims route highway hwy bit bits'.split())
LEGAL_LABELS = set(
    'article articles title clause clauses paragraph paragraphs amendment '
    'resolution circular'.split())


def reference_value(text):
    """Recognize conventional labels for a following identifying number."""
    if re.search(r'[§¶]\.?(?:s)?$', text):
        return 1.45
    if re.search(r'(?:[A-Z][A-Za-z]*\.\s*)+\d+d$', text):
        return 1.15
    if re.search(r'(?:[A-Z]\.){2,}$', text):
        return 1.3
    match = re.search(r'(\w+)(\.)?$', text)
    if not match:
        return 0.0
    word, dot = match.groups()
    low = word.lower()
    if dot and not word.isalpha():
        return 0.0
    if dot:
        parenthesis = bool(re.search(r'(?:\(|\[)\s*\w+\.$', text))
        if low in PAGE_LABELS:
            base = 1.7 if word == low else 1.2
        elif low in NOTE_LABELS:
            base = 1.6 if word == low else 0.8
        elif low in {'fig', 'figs', 'figg'}:
            return 1.15 if low != 'fig' else (0.7 if word.isupper() else 0.4)
        elif low in MONTHS:
            return 0.65
        elif low in {'no', 'num'}:
            return 1.2
        elif low in REFERENCE_ABBREVIATIONS:
            base = 1.1 if len(low) == 1 or low == 'ca' else 1.45
            if word in {'B', 'D', 'V'}:
                base = 0.4
            if low in {'art', 'cl', 'ln', 'col', 'doc', 'pl'}:
                base = 1.7
        elif low in NONNUMBER_ABBREVIATIONS:
            return 0.05
        elif len(word) == 1 and word.isupper():
            base = 0.4
        # Avoid mistaking ordinary short sentence-final words for labels.
        elif len(word) <= 5 and zipf_frequency(low, 'en') < 4.5:
            base = 1.1
        else:
            return 0.1
        boost = 0.75 if low in {'b', 'c', 'd', 'ca'} else 0.35
        return base + boost * parenthesis
    if low in {'pg', 'fn'}:
        return 1.3
    if low == 'article':
        return 1.6
    if low == 'steps':
        return 0.7
    if low in LEGAL_LABELS:
        return 1.25
    if low in PRECISE_LABELS:
        return 0.85
    if low in NUMBER_LABELS:
        return 0.4
    if word.isupper() and 2 <= len(word) <= 5:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, trace = '', 0.0
    else:
        _, previous, trace = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' ', '\u00a0'):
        trace = reference_value(previous)
        if token == '\u00a0':
            trace *= 0.65
        value = trace - 0.025
    elif token.isascii() and token.isdigit():
        value = 0.28 * trace
        trace = 0.0
    else:
        trace = 0.0
        if token == '.':
            match = re.search(r'(\w+)$', previous)
            word = match[0] if match else ''
            low = word.lower()
            if low in MONTHS:
                value = -0.3
            elif word in {'p', 'pp', 'pg', 'pág', 'págs', 'fn'}:
                value = 0.6
            elif low in {'art', 'ch', 'cap', 'cl', 'ln', 'col', 'doc', 'app', 'v'}:
                value = 0.3
        elif token == ' (' and previous.endswith('subparagraph'):
            value = 0.8
    return (doc, (previous + token)[-100:], trace), value

"""Approximate a mostly quiet component with a document-onset response.

At the first token, spelling shape matters: space-prefixed words receive a
larger positive offset, while markup and some punctuation receive negative
offsets. Capitalized test labels and HTML declaration openers are distinctive
large positive cases. Later tokens use a small constant; this deliberately
leaves most of the component's fine lexical/contextual variation unexplained.
"""
READS = ()


def onset(text):
    if text == ' Test':
        return 2.14
    if text == 'Test':
        return 1.275
    if text == '<!':
        return 2.76
    word = text.strip()
    if text.startswith(' '):
        if not word:
            return 0.023
        return 0.401 if len(word) >= 6 else 0.277
    if len(word) == 1:
        if word == '#':
            return -0.230
        return -0.101 if word == ',' else 0.081
    if '<' in word or '>' in word:
        return -0.051
    if word.islower():
        if len(word) > 4 and word.endswith('ing'):
            return -0.279
        return -0.077 if '#' in word else 0.247
    return -0.452 if '*' in word else 0.121


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    value = onset(prefix.token_strings[-1]) if first else 0.0025
    return doc, value

"""A small multilingual age-versus-duration predictor.

Age, era, school grade and scale vocabulary usually give positive writes.
Interval endings and quantities per unit of time usually give negative writes.
The strengths differ by expression: years-long intervals are stronger than
weeks-long ones. Interest/taste is a secondary positive lexical family.
Comment openers at document starts and repeated middle dots/carets have
negative baselines.
Everything else is zero. A short byte buffer joins split UTF-8 characters;
state resets at document boundaries. This is only a partial explanation.
"""
import re

READS = ()

TIME_UNITS = ('時間', '时间', '小时', '小時', '分钟', '分鐘', '星期',
              '年', '月', '週', '周', '日', '天', '時', '时', '分', '秒', '岁', '歲')
COUNT_PREFIX = re.compile(
    r'[0-9０-９一二三四五六七八九十百千万零〇半数幾几多余餘个個ヶか]*$'
)
CALENDAR_PREFIXES = {'今', '去', '明', '本', '每', '毎', '上半', '下半', '翌', '昨'}
WITHIN = {'以内', '以內', '内', '內', '中', '当中', '里', '裡',
          '的时间', '的時間', '时间', '時間', '的时间里', '的時間裡'}
RATES = {'均', '平均', '利率', '收入', '銷', '销', '产', '產', '度',
         '排行', '运营', '销量', '銷量', '产量', '產量', '产品', '產品', '产品的'}
AGE_SUFFIXES = {'纪', '紀', '少', '老', '層', '层', '期', '生', '仅', '僅',
                '華', '华', '季', '头', '頭', '次'}


def time_unit(previous_word):
    """A bare unit, counted unit, or calendar expression, not e.g. 部分."""
    token = previous_word.strip()
    for unit in TIME_UNITS:
        if token.endswith(unit):
            head = token[:-len(unit)]
            if COUNT_PREFIX.fullmatch(head) or head in CALENDAR_PREFIXES:
                return unit
    return ''


def predict(before, word, previous_word):
    if not before:
        if word.startswith('#!/'):
            return -0.9
        if word in ('//\n', '//\r\n'):
            return -2.8
        if word == '//':
            return -0.2
        if word.startswith('/*') and word.count('*') <= 2:
            return -1.3 if word.startswith('/**') else -1.8
    if len(word) >= 2 and set(word) == {'·'}:
        return -0.32
    if len(word) >= 3 and set(word) == {'^'}:
        return -0.23
    if word == '年代':
        return 4.7
    if word in ('年级', '年級'):
        return 3.5
    if word in ('年纪', '年紀'):
        return 4.5
    if word in ('年龄', '年齡'):
        return 1.9
    if word in ('规模', '規模', '大规模', '大規模'):
        return 1.6
    if word == '味':
        return 3.5 if before.endswith('興') else 0.6
    if word == ' age':
        if before.endswith((' young', ' youngest', ' tender')):
            return 1.5
        if before.endswith((' older', ' younger', '-year')):
            return 1.0
        if re.search(r'\b(years?|yrs?) of$', before):
            return 1.1
        if re.search(r'\b(months?|weeks?|days?) of$', before):
            return 0.35
        return 0.0

    unit = time_unit(previous_word)
    if unit:
        if word.startswith(('間', '间')):
            strength = {'年': 4.9, '月': 4.2, '週': 2.4, '周': 2.4,
                        '日': 3.5, '分': 4.5}.get(unit, 1.3)
            if word.startswith('间') and unit == '月':
                strength = 1.0
            return -strength * (0.65 if len(word) > 1 else 1.0)
        if word in WITHIN:
            return -2.7 if unit == '年' and word in ('里', '裡', '中') else -1.4
        if word == '刊':
            return -{'日': 5.2, '週': 4.1, '周': 4.1, '月': 2.5}.get(unit, 3.0)
        if word == '速':
            return -6.3
        if word in ('額', '额'):
            return -5.8
        if word in RATES or (unit == '年' and word in ('会', '會')):
            return -1.7
        if unit == '年':
            if word == '代':
                return 6.5
            if word in ('级', '級'):
                return 5.0
            if word in ('龄', '齡', '齢'):
                return 3.4
            if word in AGE_SUFFIXES:
                return 2.3
            if word == '月':
                return 8.0
            if word == '0':
                return -2.9
        if word == '日' and unit == '月':
            return 2.8
        if word in ('的发展', '的發展', '积累', '積累'):
            return -2.8
    if word in ('年间', '年間'):
        return -1.5
    if word == '代' and before and before[-1].isdigit():
        return 1.2
    if word == '日' and before.endswith(('周', '週')):
        return 1.4
    if word == '간' and before.endswith(('년', '월', '일', '연', '주')):
        return -4.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, previous = (carry[1], carry[2]) if carry and carry[0] == doc else (b'', '')
    before = old.decode('utf-8', errors='ignore')
    joined = old + prefix.token_bytes[-1]
    word = joined.decode('utf-8', errors='ignore')[len(before):]
    value = predict(before, word, previous)
    return (doc, joined[-64:], word or previous), float(value)

"""A local spelling detector centered on v.

Negative: the first digit after a version marker, and more weakly volume
and versus abbreviations. Positive: vac- spellings and some vu- continuations.
Split voll- spellings and paired middle dots have negative responses too.
These are approximate amplitudes, not a semantic parser. Three preceding
pieces are kept; all state resets at a document boundary.
"""
import re

READS = ()
LABEL = re.compile(r'\b(version|volume|vol|v)([.: -]*)$', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, earlier = '', '', ''
    else:
        _, previous, before, earlier = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    old = previous.strip()
    digit = bool(word) and word[0] in '0123456789'
    value = 0.0

    # A version's first digit: punctuation-prefixed markers are strongest.
    if digit and previous.endswith(('v', 'V')):
        if old in ('/v', '.v', '-v', '_v'):
            value = -9.7
        elif old == 'v':
            value = -5.0
        elif old == 'V':
            value = -3.8
            if word[0] == '0':
                value = -1.0
        else:
            value = -4.0 if previous.endswith('v') else -1.5

    # Labels can be split from their number by spaces and punctuation.
    tail = (earlier + before + previous)[-60:]
    label = LABEL.search(tail)
    if label:
        name, gap = label.groups()
        name = name.lower()
        if name == 'version':
            if text == ' ' and not gap:
                value = -1.5 if previous.startswith('.') else -4.7
            elif digit:
                value = -2.0 if ':' in gap else -5.5
        elif name in ('vol', 'volume'):
            if digit or text == ' ':
                value = -1.5
            elif text == '.':
                value = -0.6
        elif name == 'v' and gap:
            if digit:
                value = -2.5
        elif text.startswith('.') and old == 'v':
            value = -0.95

    # Two-digit path versions sometimes retain a response on their zero.
    if text == '0' and previous == '1' and before in ('/v', '.v'):
        value = -5.5

    # Vac- includes vacuum, vaccination, vacating, and split spellings.
    if lower == 'vacuum':
        value = 7.2
    elif lower in ('vaccine', 'vaccines'):
        value = 1.0
    elif lower in ('vac', 'vacc'):
        value = 4.7
    if previous.endswith(('v', 'V')) and not text[:1].isspace():
        if lower == 'ac' or lower.startswith(('acc', 'acu')):
            value = 7.0
        elif lower.startswith('ak'):
            value = 2.4
        elif lower.startswith('uk'):
            value = 5.5
        elif text == 'U':
            value = 4.0
        elif lower.startswith('u'):
            value = 1.3
        elif lower.startswith('oll'):
            value = -4.5
    if old.lower() == 'vac' and text.startswith('u'):
        value = 7.0
    if old.lower() == 'vacc' and lower.startswith('in'):
        value = 2.0
    if old.lower() == 'vacuum' and lower == 'ing':
        value = 5.0
    if previous.endswith(('в', 'В')) and text.startswith('ук'):
        value = 5.0
    if previous.lower().endswith('vol') and text.startswith('l'):
        value = -3.5
    if text == '··':
        value = -1.37
    return (doc, text, previous, before), value

"""A local detector for degree-marked 'long', especially 'as/so long as'.

The large responses fall on 'long' after a degree word, and on the next 'as'.
Smaller rules cover 'long enough', 'as soon', and the comparative 'longer'.
Secondary rules detect split-word nasal/g spellings ('ong', 'anga', and n+g).
These rules approximate the main English pattern and a few spelling effects,
not all of the rarer multilingual responses. Each rule uses only the current token and its immediate predecessor.
"""

from anyascii import anyascii
from functools import lru_cache
import re

READS = ()


@lru_cache(maxsize=8192)
def romanized(text):
    return anyascii(text).lower()

# These words ask about, compare, or intensify length/duration.
LONG_DEGREE = {
    'as': 7.6,
    'so': 5.0,
    'how': 5.3,
    'too': 2.5,
    'not': 2.2,
    'very': 0.85,
    'really': 0.85,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    current = raw.strip()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2].strip()
    before = previous.lower()

    value = 0.0
    if current == 'long':
        value = LONG_DEGREE.get(before, 0.1)
    elif current == 'as':
        if previous == 'long':
            value = 9.5
        elif before == 'soon':
            value = 0.25
        elif before == 'well':
            value = -0.17
        else:
            value = -0.05
    elif current == 'enough':
        value = 3.8 if previous == 'long' else -0.2
    elif current == 'soon':
        value = 1.1 if before == 'as' else 0.1
    elif current == 'longer':
        value = 0.85 if before in {'any', 'much', 'little', 'lot'} else 0.1
    elif current == 'than' and previous == 'longer':
        value = 0.8
    elif current == 'ong':
        value = 1.5
    elif (raw == current and re.fullmatch(r'[A-Za-z]?ong', current)
          and current.lower() not in {'long', 'song'}):
        # Short, unspaced syllables: often a piece of a name.
        value = 1.7
    elif raw == current and re.fullmatch(r'ang[ae]s?', current):
        value = 0.45
    elif current in {'g', 'г', 'گ', 'ge'} and raw == current:
        # A g-sound immediately completing a nasal spelling, across scripts.
        ending = romanized(previous)
        if ending == 'on':
            value = 5.0
        elif ending.endswith(('n', 'm')):
            value = 1.0
    return None, value

"""Approximate an equation-introduction signal.

Negative pulses mark a forthcoming formula: paragraph-ending colons, 'written
as', 'given by', copulas near mathematical text, and display-math openers.
The last 240 characters supply local mathematical and grammatical context.
This captures a regular, mostly English pattern, not every lexical response.
Unrecognized cases return zero; context resets at document boundaries.
"""
import re

READS = ()
MODALS = set('would will could can should must may might shall'.split())
COPULAS = set('is are was were be being been'.split())
WRITING = set(('write written rewrite rewritten express expressed represent '
               'represented rearrange rearranged describe described define '
               'defined denote denotes').split())
STATEMENTS = set(('equation equations formula formulas inequality inequalities '
                  'identity identities relation relations relationship '
                  'relationships law laws').split())
MATH = re.compile(
    r'\b(equations?|formulas?|expressions?|values?|results?|solutions?|answers?|'
    r'functions?|derivatives?|integrals?|sums?|products?|numbers?|terms?|'
    r'matri(?:x|ces)|vectors?|probabilit\w*|area|ratio|constant\w*|'
    r'inequalit(?:y|ies)|polynomials?|determinants?|total|difference|'
    r'length|distance)\b', re.I)
INTRO = re.compile(
    r'\b(following|below|follows|example|namely|thus|therefore|hence|so|then|'
    r'we have|consider|given|defined|written|expressed|shown|such as)\b', re.I)
CONCLUSIONS = set('therefore thus hence so then'.split())
SYMBOLIC = set(('write written rewrite rewritten express expressed rearrange '
                'rearranged rearranging simplify simplified simplifying '
                'substitute substituting expand expanding').split())


def predict(s, text):
    w = s.strip().lower()
    words = re.findall(r'[a-z_][a-z_0-9]*', text[-100:].lower())
    previous = words[-1] if words else ''
    equation = '=' in text
    math = bool(MATH.search(text))
    intro = bool(INTRO.search(text))
    symbols = sum(c in '=+*/^_<>≤≥∑∫{}[]' for c in text)
    mathematical = equation or math or symbols >= 3 or '$' in text
    line_length = len(text.rsplit('\n', 1)[-1])
    newlines = s.count('\n')

    if w.endswith((':', '：')):
        if newlines >= 2:
            if previous in CONCLUSIONS:
                return -3.2 if mathematical else -0.8
            if any(v in SYMBOLIC for v in words[-2:]):
                return -3.1 if mathematical else -0.6
            if previous in {'becomes', 'have', 'get', 'obtain'}:
                return -2.7 if mathematical else -0.6
            return (-0.41 - 0.97 * equation - 0.60 * math
                    - 0.10 * (equation and math))
        if previous in SYMBOLIC and mathematical:
            return -2.8
        if any(v in STATEMENTS for v in words[-3:]):
            return -1.8
        return -0.16 if intro else -0.015
    if w == ',':
        if newlines and previous in CONCLUSIONS:
            return -3.7 if mathematical else -0.7
        if newlines >= 2:
            if line_length <= 10:
                return -1.92 if symbols > 7 else -0.88
            return -0.73 if intro else -0.41
        if previous in CONCLUSIONS:
            return -0.96 if equation else -0.28
        return -0.05 if equation else -0.015
    if w == 'as':
        if previous in {'written', 'rewritten'}:
            return -3.7
        if any(v in SYMBOLIC for v in words[-3:]):
            return -3.0 if mathematical else -1.3
        if previous in {'defined', 'represented', 'given', 'computed', 'calculated'}:
            return -1.4
        if previous == 'described':
            return 0.0
        return -0.37 if equation else -0.05
    if w == 'by':
        if previous == 'given':
            return -2.8
        if previous in {'defined', 'related'}:
            return -1.3
        if previous in WRITING or previous in {'calculated', 'obtained', 'determined'}:
            return -0.45
        return -0.02
    if w in COPULAS:
        if w == 'be':
            if previous == 'would':
                return -1.1 if mathematical else -0.4
            if equation:
                return -0.67 if previous in MODALS else -0.31
            return -0.185 if math else -0.023
        if w in {'is', 'are'}:
            if previous in STATEMENTS:
                return -1.8
            if MATH.fullmatch(previous):
                return -0.75
        if equation:
            return -0.53 if intro else -0.21
        return -0.15 if math else -0.012
    if w in {'becomes', 'become'}:
        if previous in STATEMENTS:
            return -4.7
        if MATH.fullmatch(previous):
            return -3.2
        if symbols >= 3:
            return -2.05
        return -0.69 if math else -0.03
    if w in STATEMENTS:
        return -0.74 if math else (-0.71 if equation else -0.21)
    if w in WRITING:
        if w in {'written', 'rewritten'} and previous == 'be':
            return -3.0 if mathematical else -1.0
        if previous in MODALS or previous == 'me':
            return -1.8 if mathematical else -0.5
        return -0.42 if previous in COPULAS else -0.03
    if w in {'have', 'has', 'had'}:
        return -0.37 if equation and w == 'have' else -0.03
    if w == 'to':
        if previous in {'simplifies', 'simplify', 'reduces', 'reduce'}:
            return -3.0 if mathematical else -0.5
        return -0.33 if previous in {'equal', 'equals', 'equivalent'} else 0.0
    if w == 'form':
        if previous in {'general', 'standard', 'quadratic'}:
            return -1.9
        return -0.8 if mathematical and previous == 'the' else 0.0
    if w == 'system':
        return -1.4 if mathematical and previous in {'linear', 'following'} else 0.0
    if w in {'read', 'reads'}:
        return -1.7 if math else 0.0
    if w in {'begin', '\\begin'}:
        return -1.9 if text.endswith('\\') else -0.08
    if w in {'$$', '\\(', '\\['}:
        return -1.15 if s.startswith(' ') or text.endswith('\n') else -0.025
    if newlines and not w:
        if previous in CONCLUSIONS | {'have', 'by', 'get', 'obtain'} and mathematical:
            return -1.1
        if text.rstrip().endswith(':'):
            return -0.27
        return -0.49 if intro and '$' in text else (-0.07 if intro else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (document, (text + token)[-240:]), value

programs.haiku:
"""Layer 1, MLP down-projection unit 4324: a "setting up a formula" detector.

What it does: the unit goes negative on the words and punctuation that introduce a
displayed mathematical formula or a derivation step, e.g. "Substituting[:\\n\\n]",
"Therefore[,\\n\\n]", "can be written [as]", "the equation [becomes]", "\\begin", "$$".
The strongest case is a colon followed by a line break. Its response is much larger
when an equals sign has appeared in the last 60 tokens of the same document, which is
how it tells worked maths from ordinary prose. Dot leaders ("········") give a steady
positive value. Everywhere else it predicts 0.

Values are least-squares means fitted on training text (in activation units).
"""

READS = ()

WINDOW = 60  # how far back, in tokens, to look for an equals sign

# A colon, or a comma, then a line break: the lead-in to a displayed formula.
COLON_BREAK = {":\n\n", "):\n\n", ":\n\n\n", "：\n\n"}
COMMA_BREAK = {",\n\n"}
# LaTeX / display-maths openers.
LATEX_OPEN = {" $$", "$$", " $\\", " \\(", "begin"}
# Words that announce an equation, a relation or a rewriting step.
MATH_NOUNS = {
    " equation", " equations", " written", " write", " becomes", " form", " relation",
    " formula", " expression", " law", " terms", " gives", " equal", " relationship",
    " condition", " system", " recurrence", " recursion", " sides", " follows",
    " below", " following", " would", " have",
}
# Linking words after which a formula often comes ("is", "as", "be", ...).
LINKS = {" is", " be", " as", " are", " by", " to", " that", " this"}
# Repeated middle dots, as in a table of contents.
DOT_LEADER = {"··"}


def equals_recent(prefix):
    """True if an equals sign occurs in the last WINDOW tokens of the current document."""
    doc = prefix.document_ids[-1]
    tokens = prefix.token_strings[-WINDOW - 1 : -1]
    docs = prefix.document_ids[-WINDOW - 1 : -1]
    return any("=" in s and d == doc for s, d in zip(tokens, docs))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    eq = equals_recent(prefix)
    if tok in COLON_BREAK:
        value = -0.68 - (1.11 if eq else 0.0)
    elif tok in COMMA_BREAK:
        value = -0.46 - (0.29 if eq else 0.0)
    elif tok in LATEX_OPEN:
        value = -0.49 - (0.03 if eq else 0.0)
    elif tok in MATH_NOUNS:
        value = -0.18 - (0.54 if eq else 0.0)
    elif tok in LINKS:
        value = -0.04 - (0.24 if eq else 0.0)
    elif tok in DOT_LEADER:
        value = 0.86
    else:
        value = 0.0
    return carry, float(value)

"""Listicle framing and existential "there is a", a weak detector for one residual-stream direction.

What it responds to, in the component's own activation units (fit by least squares on sampled text):
- Negative where the text is announcing an advice list or how-to topic: the word "tips" (strongly),
  list nouns such as "ways", "benefits", "steps", "techniques", "types", ("the benefits of" is
  more negative still), "how to" / "what to", and rank words such as "best", "top", "essential".
- Positive where a sentence states that something exists ("there is a", "there was an"), or
  states a need or availability ("need for", "available for", "necessary to", "the quality of").
Everything else is predicted at zero. The main limit is that most of the variance is diffuse and
context-dependent, which no short list of words captures.
"""
READS = ()

TIPS_WORD = "tips"
# nouns that open a list of ways, benefits, types or aspects
LIST_NOUNS = {
    "ways", "benefits", "steps", "reasons", "techniques", "strategies", "methods", "types",
    "examples", "things", "ideas", "tricks", "advantages", "disadvantages", "effects",
    "importance", "elements", "characteristics", "aspects", "components", "challenges", "kinds",
    "stages", "symptoms", "areas", "skills", "traits", "signs", "secrets", "habits", "factors",
}
# words that rank or praise, as in "the best", "top", "essential"
RANK_WORDS = {"best", "top", "essential", "effective", "helpful", "useful", "basic", "key",
              "important", "main", "great", "simple", "easy", "most"}
HOW_BEFORE_TO = {"how", "what", "ways", "methods", "learn", "tips"}
NEED_BEFORE_FOR = {"need", "needed", "available", "provided", "support"}
NEED_BEFORE_TO = {"necessary", "right", "answer", "response", "need", "time", "order", "way",
                  "opportunity", "required", "expected"}
QUALITY_BEFORE_OF = {"quality", "purpose", "purposes", "strength", "source", "benefit", "name",
                     "beginning", "safety", "style", "meaning", "performance", "goal"}
BE_WORDS = {"is", "was", "are", "were", "s", "’s", "'s"}


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    strings = prefix.token_strings
    word = strings[-1].strip().lower()
    before = before2 = ""
    if len(strings) > 1 and docs[-2] == docs[-1]:
        before = strings[-2].strip().lower()
        if len(strings) > 2 and docs[-3] == docs[-1]:
            before2 = strings[-3].strip().lower()
    value = 0.0
    if word == TIPS_WORD:
        value = -2.0
    elif word in LIST_NOUNS:
        value = -0.25
    elif word in RANK_WORDS:
        value = -0.1
    elif word in ("a", "an") and before in BE_WORDS and before2 == "there":
        value = 0.65
    elif word == "to" and before in HOW_BEFORE_TO:
        value = -0.8
    elif word == "of" and before in LIST_NOUNS:
        value = -0.45
    elif word == "for" and before in NEED_BEFORE_FOR:
        value = 0.4
    elif word == "to" and before in NEED_BEFORE_TO:
        value = 0.13
    elif word == "of" and before in QUALITY_BEFORE_OF:
        value = 0.3
    return None, value

programs.sol:
"""Sparse written-form responses, plus a document-opening response.

Predict negative values for Chinese guide/lead forms (导/導), Latin 'dao',
and Korean 도, with smaller responses inside longer Korean tokens.  Some
other written syllables and two Japanese compound words have separate rules.
Opening formatting marks, and identical repetitions of them, have fixed
responses; an initial 'Title:' has a particularly negative colon.  Other
opening tokens get a small positive baseline, and most other tokens get zero.
This is a coarse approximation, not a model of all contextual variation.
"""
from anyascii import anyascii
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, previous, opening_run = 0, '', True
    else:
        _, n, previous, opening_run = carry
        opening_run = opening_run and s == previous

    word = s.strip()
    value = 0.0
    if '导' in word or '導' in word:
        if word in ('导', '導'):
            value = -5.5 if word == '导' else -5.8
            if previous.strip() == '超':
                value = -2.8
        else:
            value = -2.0
            if '领导' in word or '領導' in word:
                value = -4.4 if len(word) == 2 else -2.0
    elif '盗' in word or '盜' in word:
        value = -3.5 if len(word) == 1 else -1.1
    elif word == '入' and previous == '導':
        value = -2.0
    elif word == '道':
        value = -2.2 if previous == '報' else -0.6
    elif '报道' in word or '報道' in word:
        value = -1.7
    elif '도' in word:
        value = -2.9 / len(word)
    elif word == 'ด':
        value = 2.3
    elif word == 'до':
        value = -0.7
    elif word == 'ό' and previous.strip().endswith(('Δ', 'δ')):
        value = -0.85
    elif regex.fullmatch(r'[\p{Latin}\p{M} ._/]+', word) and (
        anyascii(word).strip(' ._/').lower() == 'dao'
    ):
        value = -4.5

    # Self-repetition preserves several document-opening formatting responses.
    if opening_run:
        value = {
            '\r': -1.95, '\\n': 3.8, '\\t': 5.1, '\\"': 2.7,
            '^^^^': 4.17, '··': 1.57, '<!': -2.14, 'Title': 0.93,
        }.get(s, value if value else 0.15)
    if n == 1 and previous == 'Title' and s == ':':
        value = -11.35

    return (doc, n + 1, s, opening_run), float(value)

"""Partial explanation: damaged Latin spelling rather than ordinary semantics.

Infer a consistently missing letter from two different shortened English
function words, after seeing English determiners. Then flag prefixes of
common words with that same omission. Also flag private-font ligatures,
ion/ons after f-like historical s, and repeated capital-I-for-f errors.

Inline soft hyphens get a small positive value; previously observed
line-breaking soft hyphens get a negative one. Other positions receive
small baselines, including a separate document-start baseline. These
rules capture only a subset of the component's lexical variation.
"""
from functools import lru_cache
import re
from wordfreq import zipf_frequency, top_n_list

READS = ()

@lru_cache(maxsize=8192)
def confused_f(word):
    """Would replacing an anomalous capital I by f give an English word?"""
    if 'I' not in word or len(word) < 2 or word.isupper():
        return False
    corrected = word.replace('I', 'f')
    frequency = zipf_frequency(corrected, 'en')
    return frequency >= 4.0 and frequency - zipf_frequency(word, 'en') >= 2.0


# Common words, and their prefixes, with one letter consistently omitted.
# The corpus sometimes loses a font's lowercase letter during extraction.
GRAMMAR_WORDS = set('''
    the and that have has are was were can for from with this there
    they their other more than been when which would will could should
    some what where about into your these those
'''.split())
FUNCTION_OMISSIONS = {}
for _word in GRAMMAR_WORDS:
    for _letter in set(_word):
        _broken = _word.replace(_letter, '')
        if len(_broken) >= 2:
            FUNCTION_OMISSIONS.setdefault(_broken, {})[_letter] = _word
PREFIX_OMISSIONS = {}
for _word in top_n_list('en', 12000):
    if not (_word.isascii() and _word.isalpha()):
        continue
    _freq = zipf_frequency(_word, 'en')
    if _freq < 4.2:
        continue
    for _end in range(3, len(_word) + 1):
        _part = _word[:_end]
        for _letter in set(_part):
            _broken = _part.replace(_letter, '')
            if len(_broken) < 2:
                continue
            _entry = PREFIX_OMISSIONS.setdefault(_broken, {})
            _entry[_letter] = max(_entry.get(_letter, 0), _freq)

@lru_cache(maxsize=8192)
def missing_letters(word):
    word = word.lower()
    original = zipf_frequency(word, 'en')
    candidates = FUNCTION_OMISSIONS.get(word, {})
    return tuple(letter for letter, fixed in candidates.items()
                 if zipf_frequency(fixed, 'en') - original >= 2.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    beginning = carry is None or carry[0] != doc
    if beginning:
        raw, inline, linebreak, f_errors = b'', 0, 0, 0
        evidence, english = {}, 0
    else:
        _, raw, inline, linebreak, f_errors, evidence, english = carry
    token = prefix.token_strings[-1]
    data = prefix.token_bytes[-1]
    before = raw.decode('utf-8', 'ignore')
    text = (raw + data).decode('utf-8', 'ignore')
