def response(token, before):
    word = token.strip()
    before = before.replace('\\n', '\n')
    previous = before.rstrip()
    line = before.rsplit('\n', 1)[-1]
    line_start = not line.strip() or bool(re.fullmatch(r'\s*\d+\s*', line))
    if word == 'def' and not before:
        return -1.7
    if word == '<!' and not before:
        return 4.7
    if word == 'block' and previous.endswith(('{%', '{%-')):
        return 4.8
    if word == 'coding' and previous.endswith('# -*-'):
        return 3.8
    if word == 'pragma' and previous.endswith('#'):
        return 6.5
    if word == ':' and before == 'Title':
        return 11.74
    if word == '#define':
        if re.search(r'#ifndef[^\n]*\n\s*$', before):
            return 7.5
        if re.search(r'#include[^\n]*\n\s*$', before):
            return 15.5
        return 12.0
    if word == 'define' and previous.endswith('#'):
        return 8.5 if len(before) - len(previous) > 12 else 10.0
    if word == 'has' and previous.endswith('__'):
        return 4.2
    if word in ('#pragma', '#undef'):
        return 2.4
    if word == 'once' and previous.endswith('#pragma'):
        return 4.8
    if word in ('#endif', 'endif', 'ndef'):
        return 0.8
