            }[word]
            return value if token[:1].isspace() else value * 0.75
        return 0.05
    if word == 'static':
        if previous.endswith('public'):
            return 1.65
        if previous.endswith(('private', 'protected', 'internal')):
            return 1.3
        return 0.9 if line_start else 0.1
    if word in ('class', 'interface'):
        modifiers = ('public', 'private', 'final', 'static', 'abstract')
        return 0.6 if previous.endswith(modifiers) else 0.05
    if word == 'fn':
        return 0.5 if previous.endswith('pub') else 0.3
    if word in ('def', 'func', 'function'):
        if previous.endswith(('public', 'private', 'static')):
            return -0.1 if word == 'function' else 0.4
        if line_start:
            if word == 'function':
                return 0.75
            return 0.35 if token[:1].isspace() else 0.95
        return 0.03
    if word == 'export' and line_start:
        return 0.95
    if word == 'pub' and line_start:
        return 0.4
    if word == 'staticmethod':
        return 1.3
    if word in ('Override', '@Override'):
        return 0.87
    rust_attributes = ('warn', 'deny', 'allow', 'derive', 'feature')
    if word in rust_attributes and previous.endswith(('#[', '#![')):
        return {'warn': 3.8, 'deny': 5.0, 'allow': 2.2,
                'derive': 3.0, 'feature': 5.0}[word]
