"""layers.1.mlp.down_proj:4330 -- a "code declaration / directive opener" detector.

What it does, in plain terms. This component writes into the residual stream when the
text is source code and the current token opens a declaration or a directive:

  * C preprocessor `#define` (the word "define" after "#"): by far the strongest response,
    about 11. `#pragma once` ("once" after "pragma") about 6.
  * Attribute / tag openers: the name right after `#[` or `#![` (Rust: derive, warn,
    deny, feature) about 3.5, other attribute names about 0.5; the name right after a Javadoc `{@` (`{@link`) about 5;
    the word after a Jinja `{%` (`{% block`) about 4.5; `@Override` after `@` about 0.8.
  * Method/function declaration openers at the start of a source line: access modifiers
    `public`, `private`, `protected`, `static` (about 1; "static" after another modifier
    likewise), and `function`, `procedure`, `export`, `impl` (0.7 to 1), `def`, `fn`, `func`
    (0.4 to 0.5). The same words in English prose ("the public", "function of") are ~0.
  * A corpus artifact: the token ":" in a "Title:" line that opens a document is about 11.7.
  * Document and row boundaries: the first token after <|endoftext|> is about -0.35, and the
    first token of a row about -0.15.

Everything else predicts 0. Line-start is tracked from the carry: a line starts after a
newline, and whitespace since then does not end it.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
ACCESS_MODIFIERS = {"public", "private", "protected", "static", "final", "abstract"}
# Words that open a function or method declaration, with their typical activation at line start.
DECLARATION_OPENERS = {
    "function": 1.0, "procedure": 0.8, "export": 0.7, "impl": 0.7,
    "def": 0.5, "fn": 0.4, "func": 0.4, "void": 0.3, "pub": 0.3,
}
# Words after `#` that name a C preprocessor directive, with their typical activation.
PREPROCESSOR = {"define": 11.0, "pragma": 2.0, "endif": 0.8}
# Attribute names after `#[` or `#![`.
ATTRIBUTE_NAMES = {"derive", "warn", "feature", "deny"}


def step(carry, prefix, upstream):
    # carry: (at_line_start, after_modifier, previous_token), or None at a row's first token.
    if carry is None:
        at_line_start, after_modifier, previous = True, False, "<row>"
    elif prefix.document_ids[-1] != prefix.document_ids[-2]:
        at_line_start, after_modifier, previous = True, False, END_OF_TEXT
    else:
        at_line_start, after_modifier, previous = carry

    tokens = prefix.token_strings
    text = tokens[-1]
    word = text.strip()
    value = 0.0
    if word.lstrip("#") in PREPROCESSOR and (word.startswith("#") or previous == "#"):
        value = PREPROCESSOR[word.lstrip("#")]
    elif word == "once" and previous == "pragma":
        value = 6.0
    elif word == ":" and previous == "Title" and (len(tokens) == 2 or tokens[-3] == END_OF_TEXT):
        value = 11.0
    elif previous == "<row>":
        value = -0.15
    elif previous == END_OF_TEXT:
        value = -0.35
    elif previous in ("#[", "#!["):
        value = 3.5 if word in ATTRIBUTE_NAMES else 0.5
    elif word == "link" and previous == "{@":
        value = 5.0
    elif word == "block" and previous in ("{%", "{%-"):
        value = 4.5
    elif word == "Override" and previous == "@":
        value = 0.8
    elif word in ACCESS_MODIFIERS and (at_line_start or after_modifier):
        value = 1.0
    elif word in DECLARATION_OPENERS:
        value = DECLARATION_OPENERS[word] if at_line_start else 0.3

    after_modifier = word in ACCESS_MODIFIERS and (at_line_start or after_modifier)
