    if 'ő' in low:
        value -= 0.4 + 0.36 * word_initial + 2.93 * t[:1].isupper()
    if 'ě' in low:
        value -= 0.13
    if 'я' in low:
        value -= 0.11 + 1.01 * bg if low == 'я' else 0.2 * bg
        if word_initial:
            value += 0.35 * bg
    if 'щ' in low:
        value -= 0.08 + 0.31 * bg
        if word_initial:
            value -= 0.03 + 0.61 * bg
    if text[:1].isalpha() and text.isascii():
        if 'ä' in previous.lower():
            value -= 0.94 * sv
        if 'å' in previous.lower():
            value -= 0.18 + 0.26 * sv
    if '\ufffd' in prefix.token_strings[-1] and b != b'\xef\xbf\xbd':
        value -= 2.25 * bg
    if len(t) > 1 and set(t) == {'·'}:
        value += 1.18
    return (doc, tail, votes, text, pending), value

"""A detector of relational connectors, mostly binary mathematical operators.

Spaced operators and operators following an operand receive negative values.
A short text tail distinguishes mathematical expressions from program syntax,
where assignment and list punctuation have weaker responses. Ordinary text
is near zero; a few English comparison, direction and time connectors get
smaller responses. Multiword frames such as "ratio of A to B", "mix A with
B" and "separate A from B" strengthen their final connector. The tail resets
at document boundaries.
"""
import re

READS = ()

MATH = re.compile(
    r'\\[a-zA-Z]|[=+^×÷≤≥]|\b(equation|solve|equal|sum|fraction|integral|slope)\b'
)
CODE = re.compile(
    r'[{};]|\b(return|const|let|var|def|class|function|import|public|void|int)\b'
)
SINGLE_LETTER = re.compile(r'(?:^|[\W_])[a-zA-Z]$')

# Multiword binary relations: cue, first argument, then the connector.
RELATION_CUES = {
    'to': r'ratio|from|equal|equivalent|proportional|relative|similar|compared',
    'with': r'mix\w*|combin\w*|blend\w*|pair\w*|match\w*|compar\w*|associat\w*',
    'from': r'separat\w*|differ\w*|distinct\w*|distinguish\w*|subtract\w*',
    'by': r'divided|multiplied',
    'given': r'probability|probabilities|conditional|likelihood|evidence',
    'then': r'if',
}
RELATION_CUES = {w: re.compile(r'\b(' + p + r')\b', re.I)
                 for w, p in RELATION_CUES.items()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    before = recent.rstrip()
    last = before[-1:] or ' '
    spaced = token[:1].isspace()
    number = last.isdigit()
    close = last in ')]}'
    letter = bool(SINGLE_LETTER.search(before))
    operand = number or close or letter
    operator = last in '+-=*/<>|&'
    punctuation = last in ',.;:!?'
    line_start = not recent.rsplit('\n', 1)[-1].strip()
    math = bool(MATH.search(recent))
    code = bool(CODE.search(recent))
    # Parentheses can share a token with the operator between expressions.
    symbol = word.strip('()[]{}.,;:')
    value = 0.0
    if symbol in {'+', '±', '∓'}:
        value = (-0.75 - 0.8*spaced - 0.5*operand - 0.5*math
                 + 0.7*code + 0.4*punctuation + 0.3*line_start + 0.2*operator)
    elif symbol in {'-', '−', '--'}:
        value = (0.1 - 0.5*spaced - 0.55*operand - 0.5*math
                 + 0.6*operator + 0.2*code + 0.1*punctuation)
    elif word in {'–', '—'}:
        value = -0.2 - 0.6*math
    elif symbol in {'->', '-->', '<-', '→', '⇒', '↔', '⇔', '↦'}:
        value = -1.75 - 0.6*spaced + 0.6*number + 0.7*math + 0.5*code
    elif symbol in {'=>', '<=>'}:
        value = -0.53
    elif symbol == '=':
        value = (-0.05 - 0.27*spaced - 0.25*number - 0.2*close
                 - 0.1*letter + 0.3*code - 0.05*math)
    elif symbol in {'==', '===', '!=', '!==', '≠', '≈', '≃', '≡', '≅', '~='}:
        value = -0.35 - 0.35*spaced
    elif symbol in {'<', '>', '<=', '>=', '≤', '≥', '≪', '≫'}:
        value = (-0.15 - 0.5*spaced - 0.13*number - 0.32*close
                 - 0.4*letter + 0.36*operator + 0.15*line_start)
    elif symbol == '/':
        value = (-0.15 - 0.2*spaced - 0.1*number - 0.5*close
                 - 0.3*letter - 0.25*math + 0.15*code
                 + 0.2*punctuation + 0.15*operator)
    elif symbol in {'*', '×', '÷', '⋅', '·', '∗'}:
        value = (-0.55 - 0.5*close - 0.2*math + 0.2*code
                 + 0.35*line_start + 0.15*punctuation)
    elif symbol in {'&&', '||', '∧', '∨'}:
        value = -1.1
    elif symbol in {'&', '|', '∩', '∪', '⊕'}:
        value = (-0.18 - 0.32*spaced - 0.2*close + 0.3*number
                 + 0.2*operator + 0.15*line_start)
    elif symbol in {'<<', '>>'}:
        value = -0.6 - 0.3*spaced
    elif symbol in {'^', '**', '%'}:
        value = -0.1 - 0.1*spaced
    elif word == ':':
        value = -0.42 if spaced else 0.0
    elif word == '?':
        value = -0.05 - 0.13*spaced - 0.1*code
    elif re.fullmatch(r'[)\]}]+[(\[{]+', word):
        value = -0.2 - 0.2*math
    elif word in {'cdot', 'times', 'div', 'pm', 'mp', 'ast', 'circ'} and before.endswith('\\'):
        value = -0.5
    elif word in {'和', '与', '或', '跟', '从', '向', '对', '比', '及'}:
        value = -0.16
    elif word == word.lower():
        if word in {'to', 'toward', 'towards', 'into', 'onto'}:
            value = -0.09 - 0.42*number - 0.31*letter - 0.15*close - 0.09*math
        elif word in {'than', 'versus', 'vs'}:
            value = -0.6
        elif word in {'before', 'until', 'over', 'under', 'per', 'while'}:
            value = -0.2
        elif word in {'with', 'without'}:
            value = -0.12 + 0.12*punctuation
        elif word in {'equals', 'equal', 'becomes', 'implies'}:
            value = -0.5 - 0.4*letter
        elif word in {'divided', 'times', 'plus', 'minus', 'mod'}:
            value = -0.35 - 0.3*(close or letter) - 0.2*math
        elif word == 'then':
            value = -0.3
        elif word in {'and', 'or', 'nor'}:
            value = -0.1*operand - 0.07*math
    if symbol in {'-', '−'} and math and operand and not code and not line_start:
        value -= 0.3
    if symbol in {'→', '⇒', '↔', '⇔', '↦'}:
        value = -1.3
    if word in RELATION_CUES:
        # Bound the scope: don't carry a cue across a full stop or blank line.
        clause = re.split(r'[.!?]|\n\s*\n', recent)[-1][-100:]
        cue_text = re.sub(
            r'\bratio\b(?!\s+(of|between)\b)', '', clause, flags=re.I
        )
        if RELATION_CUES[word].search(cue_text):
            value = {'to': -0.9, 'with': -0.7, 'from': -0.9,
                     'by': -0.9, 'given': -1.1, 'then': -0.9}[word]
            if word == 'to' and re.search(r'\bratio\s+(of|between)\b', clause, re.I):
                value = -2.5
    if word == 'then' and code:
        value = 0.0
    if word == 'mod':
        value = -0.9 if operand and math and not code else 0.0
    return (doc, (recent + token)[-120:]), float(value)

"""Detect selected prepositions, modulated by their immediate grammatical context.

By, in, into, from and for carry most of the positive signal. A preceding
verb, copula, object pronoun or past verb form often strengthens it.
Dictionary motion classes boost 'into'; stative classes can reduce 'by'. Other
prepositions are mostly quiet, except in constructions such as 'based on',
'according to' and 'because of'. This is a local heuristic, not a parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
COPULAS = set('am is are was were be been being'.split())
OBJECTS = set(('me you him her us them it myself yourself himself herself '
               'itself ourselves themselves').split())
CONJUNCTIONS = set('and or but that which than so then'.split())
PARTICLES = set('up out down back away in off through'.split())
REPUTATION = set(('known famous notorious renowned noted celebrated infamous '
                  'recognized').split())
QUANTITATIVE_CHANGE = set('change increase decrease difference result'.split())
# Heads of familiar multiword prepositions ending in 'of'.
COMPOUND_OF = {
    'out': .74, 'because': .65, 'front': .62, 'basis': .69,
    'help': .64, 'means': .43, 'terms': .31,
}
# Lexical levels, also used for case/spacing variants and foreign prepositions.
LEXICAL = {
    'by': 1., 'in': .54, 'for': .44, 'from': .56, 'into': .71,
    'to': .014, 'of': -.018, 'on': -.012, 'with': -.024,
    'at': -.05, 'as': -.037, 'over': -.059, 'before': .065, 'after': .05,
    'por': .83, 'par': .57, 'pour': .38, 'pela': 1.25, 'pelo': 1.05,
    'im': .34, 'ins': .38, 'durch': .32, 'para': .24, 'per': .11,
    'en': .09, 'em': .09, 'de': -.015, 'con': -.116, 'dans': -.068,
    'в': .16, 'из': .26, 'от': .11, 'для': .14, 'für': .13,
}

@lru_cache(maxsize=8192)
def grammar(word):
    if not word.isalpha():
        return set(), (), set()
    return (wordnet.parts_of_speech(word), wordnet.base_forms(word),
            wordnet.categories(word))


def contextual(preposition, previous):
    pos, roots, meanings = grammar(previous)
    verb = 'verb' in pos
    adjective = 'adjective' in pos
    noun = 'noun' in pos
    # Approximate past forms: -ed, or a verb whose dictionary root differs,
    # excluding present -s/-ing forms and the copula.
    past = previous.endswith('ed') or (
        verb and previous not in COPULAS
        and not previous.endswith(('s', 'ing'))
        and any(root != previous for root in roots))
    punctuation = bool(previous) and not previous.isalpha()
    if preposition == 'in':
        if previous == 'available':
            return 1.14
        if any(root in QUANTITATIVE_CHANGE for root in roots):
            return .09
        if verb:
            return .94 if previous in COPULAS else .73 if past else .57
        if previous in OBJECTS:
            return .90
        return .25 if previous in CONJUNCTIONS else .44
    if preposition == 'by':
        if previous in {'divided', 'multiplied', 'divisible'}:
            return .35
        if past:
            if 'verb.stative' in meanings and 'verb.communication' not in meanings:
                return .84
            return 1.31
        return 1.03 if 'adverb' in pos else .74
    if preposition == 'for':
        if previous == 'available':
            return .70
        if previous in REPUTATION:
            return 1.75
        if previous in {'thank', 'thanks'}:
            return 1.15
        if punctuation:
            return .22
        if previous in OBJECTS:
            return 1.05
        return .08 if previous in CONJUNCTIONS else .46
    if preposition == 'from':
        if punctuation:
            return .34
        return .68 if past or previous in PARTICLES else .56
    if preposition == 'into':
        return .93 if 'verb.motion' in meanings else .59
    if preposition == 'of':
        if previous in COMPOUND_OF:
            return COMPOUND_OF[previous]
        if verb and past:
            return .13
        return -.20 if previous in CONJUNCTIONS else -.025
    if preposition == 'on':
        if previous == 'based':
            return .73
        if previous.startswith('depend'):
            return .43
        return -.11 if noun else 0.
    if preposition == 'to':
        if previous == 'available':
            return .80
        if previous == 'according':
            return .77
        if previous in {'due', 'pursuant'}:
            return .56
        if previous.endswith('ing'):
            return .45 if adjective and not noun else .06
        if adjective:
            return .12 if not verb else .006
        return -.053 if noun else .038
    if preposition == 'with':
        if previous == 'accordance':
            return .47
        if previous in {'along', 'together', 'consistent'}:
            return .18
        if previous in CONJUNCTIONS:
            return -.18
        return -.05 if noun else .01
    return LEXICAL[preposition]


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = LEXICAL.get(word, 0.)
    if word in LEXICAL:
        if token == ' ' + word:
            words = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?|[^\w\s]", tail)
            previous = words[-1].lower() if words else ''
            value = contextual(word, previous)
        elif token.strip().istitle():
            value *= .3
        elif not token.startswith(' '):
            value *= .3
        elif token.strip().isupper():
            value *= .65
    if token == '-in':
        value = .59
    return (document, (tail + token)[-100:]), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 4337: a fixed-phrase detector.

What it does: this component is silent almost everywhere (it is non-zero on about 0.05% of
tokens) and, when it fires, it fires negatively on the word that completes a set phrase whose
next word is nearly fixed. Its largest values come from these phrases:

- "At the end", "By the time", "At the beginning/start/close/age", "At room" (temperature),
  "At birth": the time or place noun after "at"/"by the" is strongly negative. The "of" that
  follows such a noun ("the end of", "the time of") is also strongly negative.
- "if and only if": the "and" after "if" is strongly negative.
- Python idioms: "__" in "if __name__" / "from __future__" (the strongest values), then the
  "name"/"future" after it; "Exception" after "except"; "isinstance" after "if", "elif" or "not".
- "=== RUN" in Go test logs.

Mildly positive: "of" after relation nouns ("on the basis of", "at the level of", "range of",
"cost of"). Everything else is 0. Predictions are in the component's activation units.
"""

READS = ()

TIME_NOUNS = {" end", " time", " beginning", " start", " close", " conclusion",
              " finish", " age", " birth", " front", " far", " outset", " onset"}
STRONG_NOUNS = {" end", " close", " age", " far"}
RELATION_NOUNS = {" basis", " level", " range", " cost", " context", " expense", " angle"}
AT_OR_BY = {" at", " At", " by", " By", " until"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]

    def back(k):
        # the token k places before the current one, or "" across a document boundary
        same = len(toks) > k and prefix.document_ids[-1 - k] == prefix.document_ids[-1]
        return toks[-1 - k] if same else ""

    prev, prev2, prev3 = back(1), back(2), back(3)
    value = 0.0
    if cur in TIME_NOUNS and prev == " the" and prev2 in AT_OR_BY:
        value = -3.0 if cur in STRONG_NOUNS else -2.0          # "At the end", "By the time"
    elif cur in TIME_NOUNS and prev == " the":
        value = -0.7                                           # "the time", "the end" elsewhere
    elif cur == " room" and prev == " at":
        value = -3.5                                           # "at room temperature"
    elif cur == " of" and prev in TIME_NOUNS and prev2 == " the" and prev3 in AT_OR_BY:
        value = -3.5                                           # "At the end of"
    elif cur == " and" and prev == " if":
        value = -4.0                                           # "if and only if"
    elif cur == " RUN" and prev == "===":
        value = -2.2                                           # Go test log "=== RUN"
    elif cur == " __" and prev in ("if", "from", "\tif", "\tfrom"):
        value = -8.0                                           # "if __name__", "from __future__"
    elif cur in ("name", "future") and prev in (" __", "__"):
        value = -4.0
    elif cur == " Exception" and prev == "except":
        value = -2.8
    elif cur == " isinstance" and prev in (" if", " elif", " not"):
        value = -2.0
    elif cur == " of" and prev in RELATION_NOUNS:
        value = 0.8                                            # "on the basis of", "range of"
    return carry, float(value)

programs.sol:
"""Estimate boundary-related activation, rather than memorizing token scores.

English word frequencies detect familiar words joined into an unfamiliar
combination. Capitalized words attached to a stop are another boundary cue.
Numerals attached to function words and escaped-newline fragments also pulse.
Separate rules cover chat/tool headers, document
starts, and the large pulse on the colon of an initial 'Title:' label.
These rules only approximate the component; most text receives zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=50000)
def frequency(word):
    return zipf_frequency(word.lower(), 'en') if word else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, prev, before, recent = 0, '', '', ''
    else:
        _, n, prev, before, recent = carry
    a = s.strip()
    code = any(ch in recent for ch in '{}_=<>;')
    value = 0.0

    if n == 0:
        if s == '<|im_start|>':
            value = 0.04
        elif any(ch.isalpha() for ch in s):
            value = -0.4 if a[:1].isupper() else -0.25
        else:
            value = -0.06
    elif prev == '<|im_start|>':
        if s == 'user':
            value = 0.77 if n == 1 else 1.6
        elif s == 'assistant':
            value = 0.75
    elif s == '<tool_call>':
        value = 0.39
    elif s == '<tool_response>':
        value = 0.21
    elif n == 1 and prev == 'Title' and s == ':':
        value = 12.65
    elif not code:
        if len(s) > 1 and s[0] == '.' and s[1:].isalpha():
            if s[1].isupper():
                if frequency(s[1:]) > 6.75 and s[1:].istitle():
                    value = 2.3 if len(before) > 3 else 0.6
                else:
                    value = 0.65 if len(before) > 3 else 0.1
        elif s.isalpha() and prev and prev[-1] in '.!?' and s[0].isupper():
            value = 2.0 if frequency(s) > 5.5 else 0.8
        elif s.isalpha() and before and s.islower():
            left, right = frequency(before), frequency(s)
            if min(left, right) > 4 and frequency(before + s) < 0.5:
                # A very common word is less likely to be a suffix or a name.
                value = 0.12
                if max(left, right) > 6.5:
                    value = 0.6
                if min(left, right) > 6.5:
                    value = 1.0
        elif (s[:1].isdigit() and before.lower() in
              {'by', 'to', 'from', 'of', 'in', 'at', 'with', 'than', 'and'}):
            value = 0.8
        elif (s.startswith(' ') and a.istitle() and frequency(a) > 6.75
              and prev and prev[-1].islower()):
            value = 0.25

    if prev.endswith('\\') and len(s) > 1 and s[0] == 'n' and s.isalpha():
        value = 0.65
    match = re.search(r'[^\W\d_]+$', s)
    before = (before + s if s.isalpha() else
              match.group() if match else '')[-48:]
    recent = (recent + s)[-100:]
    return (doc, n + 1, s, before, recent), value

programs.haiku:
"""Layer-1 MLP down-projection component 4339.

A sparse feature: near zero on most tokens, it fires on a few recognisable kinds of token,
and is mildly negative on the first token of a document. Predicted activation, in the
component's own units; the first rule that applies sets the value:

  * the token right after a chat-turn marker "<|im_start|>" (the role name): "user" +1.4,
    "assistant" +0.8, any other role +1.0;
  * a middle-dot filler token "··": a strong, constant negative (-1.0);
  * the ":" of "Title:", strongly positive (+3.1);
  * a sentence-initial word glued to its full stop with no space (".It", ".The", ".He" ...):
    strongly positive for pronoun/determiner starts (".It" +3.8, ".The" +2.2), mildly
    positive (+0.2) for other capitalised words after a stop;
  * tool-call markup "<tool_call>" (+0.4) and "<tool_response>" (+0.2);
  * otherwise, the first token of each document (after the row start or "<|endoftext|>"),
    mildly negative (-0.25);
  * everything else: 0.
"""

READS = ()

ROLE_AFTER_IM_START = {"user": 1.4, "assistant": 0.75}
GLUED_SENTENCE_START = {".It": 3.8, ".This": 3.1, ".He": 2.4, ".The": 2.2, ".In": 1.5}
GLUED_OTHER_CAPITAL = 0.2
TOOL_MARKUP = {"<tool_call>": 0.4, "<tool_response>": 0.2}
MIDDLE_DOT_FILLER = -1.0
FIRST_TOKEN_OF_DOCUMENT = -0.25


def rule_value(tok, prev):
    if prev == "<|im_start|>":
        return ROLE_AFTER_IM_START.get(tok, 1.0)
    if tok == "··":
        return MIDDLE_DOT_FILLER
    if tok == ":" and prev == "Title":
        return 3.1
    if tok in GLUED_SENTENCE_START:
        return GLUED_SENTENCE_START[tok]
    if len(tok) > 1 and tok[0] == "." and tok[1].isupper():
        return GLUED_OTHER_CAPITAL
    if tok in TOOL_MARKUP:
        return TOOL_MARKUP[tok]
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = rule_value(tok, prev)
    first = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if value == 0.0 and first:
        value = FIRST_TOKEN_OF_DOCUMENT
    return carry, float(value)

programs.sol:
"""A spelling-sensitive mathematics-word detector.

Predict large positive responses to math/mathematics and their split word
endings, including several non-English spellings. Capitalization and the
part of the word just completed change the strength. Programming-library
uses are weaker, while TeX commands are mostly suppressed. Everything else
is near zero. Responses are damped at document starts. The short text tail
is reset at document breaks. Small background responses are not modeled.
"""
import re
import unicodedata

READS = ()


def response(old, token):
    low = token.lower()
    match = re.search(r'[^\W\d_]+\Z', (old + token).lower())
    word = match.group() if match else ''
    word = ''.join(c for c in unicodedata.normalize('NFD', word)
                   if not unicodedata.combining(c))

    if '数学' in token or token == '学' and old.endswith('数'):
        return 8.8
    if '수학' in token or token == '학' and old.endswith('수'):
        return 9.0
    if 'матем' in word:
        if word.endswith('матем'):
            return 8.4
        if word.endswith('математ'):
            return 13.7
        if re.search(r'математик[аи]?\Z', word):
            return 6.5
        return 4.4
    if word == 'мат':
        return 0.9
    if not re.search('math|matem', word):
        if low == 'al' and old.lower().endswith('ematic'):
            return 5.0
        return 0.4 if low.strip() in ('mat', 'mats') else 0.0

    if re.search(r'\\(?:ensure|bold|unbold)?\Z', old) and low == 'math':
        return 0.0
    if low in ('(math', '*math', ')math'):
        return 1.3
    if 'aftermath' in word:
        return 0.2
    if low.strip() == 'mathf':  # Unity's distinct library identifier.
        return -1.0
    capital = token.strip()[0].isupper()
    if low.strip() == 'mathematical':
        return 9.4 if capital else 8.2
    if low.strip() == 'mathematics':
        return 8.8 if capital else 6.5
    if low.strip() == 'mathematic':
        return 5.5
    if low.strip() == 'maths':
        return 8.3 if capital else 7.5

    if low.strip() == 'math' or low in ('.math', '/math', '_math', '"math', 'cmath'):
        if token == 'math' and old and old[-1].isalpha():
            return 9.0
        code = re.search(r'\b(?:import|from|return) *\Z|'
                         r'\bimport [\w.]+ *\Z|[=({+*] *\Z', old)
        if code or re.search(r'\bMath\.[a-z]', old[-80:]) or low == 'cmath':
            return 2.6
        return 6.0 if capital else 5.2

    if re.search(r'mathematic(?:ians?|iens?)\Z', word):
        return 1.5
    if word.endswith('mathematically'):
        return 6.8
    if word.endswith('mathematical'):
        return 10.5
    if word.endswith('mathematica'):
        return 0.3  # Final a in the software name Mathematica.
    if word.endswith('math'):
        return 9.0 if low in ('ath', 'math') else 0.0
    if word.endswith('maths'):
        return 8.0
    if word.endswith(('matics', 'matica', 'matique', 'matiques',
                      'matika', 'matik', 'matiker', 'matisch',
                      'matische', 'maticas', 'maticos')):
        return 7.5
    if word.endswith('mathem'):
        return 0.8
    if low == 'he' and word.endswith('mathe'):
        return 5.7 if token.isupper() else 10.0
    if 'matem' in word:
        return 12.0
    return 5.0 if 'mathem' in word else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(old, token)
    if not old:
        value *= 0.25  # The initial token has no supporting word context.
    return (doc, (old + token)[-120:]), value

"""Negative responses to compact bibliographic fields.

Recognize citation identifiers, page/volume labels and publishing cities.
For numeric fields, reference-like context means reference abbreviations or
several capitalized words with dense punctuation and few function words.
Keep a 160-character window. A bibliography heading, or a strong citation
label in the preceding 128 tokens, adds a learned negative field response.
Document boundaries and end-of-document markers clear that extra state.
"""
import re

READS = ()
PAGES = {'p', 'pp', 'page', 'pages'}
VOLUMES = {'vol', 'vols', 'volume'}
IDS = {'isbn', 'issn', 'doi', 'arxiv'}
CITIES = {'Berlin', 'Boston', 'Cambridge', 'Chicago', 'Leipzig', 'London',
          'Londres', 'New', 'Oxford', 'Paris', 'Wien', 'York'}
FUNCTION_WORDS = set('the a an of in to for and is was are were on from '
                     'with as by at that it which this be has had have '
                     'not will would can'.split())
CITATION_WORD = re.compile(
    r'\b(?:pp?|vol|volume|isbn|doi|issn|arxiv|press|publishing|verlag|'
    r'journal|rev|soc|trans|bull|proc|ed|eds)\b', re.I)
WORDS = re.compile(r'[A-Za-zÀ-ÿ]+')


PUBLISHERS = {'press', 'publisher', 'publishers', 'publishing',
              'soc', 'society', 'verlag'}
HEADING = re.compile(
    r'(?:^|\n|<\|endoftext\|>|<\|im_end\|>)\s*(?:#{1,6}\s*)?'
    r'(?:references|bibliography|works cited)\s*$', re.I)



def kind(s):
    w = s.strip()
    low = w.lower()
    if low in PAGES:
        return 'page'
    if low in VOLUMES:
        return 'volume'
    if low in IDS:
        return 'identifier'
    if w in CITIES:
        return 'city'
    if s == ' ':
        return 'space'
    if s.isdecimal() and s.isascii():
        return 'digit'
    if w in {':', '：'}:
        return 'colon'
    if w in {'-', '–', '—'}:
        return 'dash'
    if (w and not any(c.isalnum() for c in w) and ',' in w
            or w and all(c in '.;。' for c in w)
            or any(c in s for c in '()') and not any(c.isalpha() for c in s)):
        return 'punctuation'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry and carry[0] == doc:
        _, before, remaining, bibliography = carry
        remaining = max(remaining - 1, 0)
    else:
        before, remaining, bibliography = '', 0, False
    token = prefix.token_strings[-1]
    k = kind(token)
    w = token.strip()
    short = before[-80:]
    words = WORDS.findall(short)
    last = words[-1] if words else ''
    trim = before.rstrip()
    run = re.search(r'\d+$', before)
    digits = len(run[0]) if run else 0
    number_before = bool(re.search(r'\d+\s*$', before))
    front = before[:-digits].rstrip() if digits else trim
    boundary = front.endswith((',', ':', '.', '('))
    capitals = sum(x[0].isupper() for x in words)
    functions = sum(x.lower() in FUNCTION_WORDS for x in words)
    reference = (bool(CITATION_WORD.search(before))
                 or short.count('.') >= 2 and capitals >= 3 and functions <= 3
                 or short.count(',') >= 2 and capitals >= 4 and functions <= 2)

    def local_value():
        if k == 'space' and boundary and reference:
            if last in CITIES:
                return -3.627
            if not CITATION_WORD.fullmatch(last):
                return -0.442
            return -0.893 if last.lower() in PAGES else -2.543
        if k == 'volume' and token.startswith(' ') and (
                trim.endswith((',', '.')) or last in CITIES):
            return -4.335
        if k == 'page' and token.startswith(' ') and (
                number_before or trim.endswith((',', '.'))):
            if w[0].isupper():
                return 0.008
            if not (last and last[0].isupper()):
                return -0.609
            if not boundary:
                return -0.189
            return -3.984 if w.isalpha() and len(w) <= 3 else -1.074
        if k == 'colon' and last.lower() in IDS:
            return -3.944
        if k == 'identifier':
            return -3.899
        if k in {'punctuation', 'colon', 'dash'} and number_before and reference:
            if digits <= 2:
                return -2.413 if last.lower() in VOLUMES else -0.120
            if k == 'dash':
                return -0.076 if token.startswith(' ') else -1.514
            return -0.361
        if k == 'digit' and boundary and digits <= 1 and reference:
            return -0.121
        if k == 'city' and trim.endswith((',', '.', '(')):
            return -0.820
        return -0.002

    value = local_value()
    after = (before + token)[-160:]
    if '<|endoftext|>' in token or '<|im_end|>' in token:
        return (doc, after, 0, False), value
    capital = bool(last and last[0].isupper())
    volume_label = (k == 'volume' and token.startswith(' ')
                    and (trim.endswith((',', '.')) or last in CITIES))
    page_label = (k == 'page' and token.startswith(' ')
                  and (number_before or trim.endswith((',', '.')))
                  and w.islower() and capital and boundary and len(w) <= 3)
    if (k == 'identifier' or k == 'colon' and last.lower() in IDS
            or volume_label or page_label):
        remaining = 128
    bibliography = bibliography or bool(HEADING.search(after))
    if bibliography or remaining:
        if k == 'space' and boundary:
            value -= 0.922
        elif k == 'digit' and boundary:
            value -= 0.509 if digits == 0 else 0.358 if digits == 1 else 0.214
        elif k in {'punctuation', 'colon', 'dash'} and number_before:
            value -= 0.677
        elif w.lower() in PUBLISHERS and w[0].isupper() and capital:
            value -= 1.434
    return (doc, after, remaining, bibliography), float(value)

programs.haiku:
"""Month names in day-month dates, such as "14 Aug 2010", "Joined: 02 Sep 2009" or
"3 May 1990".

Layer 1's down_proj component 4343 is a "day-month date" detector. It fires on the
month name that comes straight after a 1- or 2-digit day number, and again on the
space after that month, which is where the year is about to be written. Abbreviated
month names ("Aug", "Sep", "Dec") fire harder than full names ("August"). Nothing else
in the text moves it much. Month names after a year, after "in", "on" or "from", or
used without a day ("in April 2010") stay at 0.

Main program: for each token, check whether it is a month name preceded by a day
number, or a space preceded by such a month. Return a fixed strength.
"""

ABBREVIATED = {"Jan", "Feb", "Mar", "Apr", "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec"}
FULL = {"January", "February", "March", "April", "May", "June", "July", "August",
        "September", "October", "November", "December"}
READS = ()

# Typical activations: abbreviated month ~10, full month ~7.5 (on the month name);
# the space after an abbreviated month ~10, after a full month ~4.
MONTH_STRENGTH = {"abbreviated": 10.0, "full": 7.5}
SPACE_STRENGTH = {"abbreviated": 10.0, "full": 4.2}


def _day_ends_before(strings, i):
    """True if a 1- or 2-digit day number ends just before index i.
    Qwen writes digits as single tokens, so the day is one or two digit tokens."""
    n = 0
    j = i - 1
    while j >= 0 and len(strings[j]) == 1 and strings[j].isdigit() and n < 3:
        n += 1
        j -= 1
    return 1 <= n <= 2


def _month_kind(word):
    if word in ABBREVIATED:
        return "abbreviated"
    if word in FULL:
        return "full"
    return None


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = len(s) - 1
    cur = s[t]
    kind = _month_kind(cur.strip())
    if kind and cur[:1] in (" ", "") and _day_ends_before(s, t):
        return carry, MONTH_STRENGTH[kind]
    if cur.strip() == "" and t >= 1:
        kind = _month_kind(s[t - 1].strip())
        if kind and _day_ends_before(s, t - 1):
            return carry, SPACE_STRENGTH[kind]
    return carry, 0.0

programs.sol:
"""Punctuation after short numbers, adjusted for the recent number format.

Periods, commas and colons usually have negative responses after digits.
The latest use of a separator helps distinguish numerical notation from prose;
commas followed by long digit groups suggest grouping/decimal-comma notation.
Fractional parts, years, and line-initial list numbers get separate treatment.
A few time units and the phrase 'because of' are also covered. This leaves
other lexical effects near zero rather than memorizing a vocabulary table.
"""
import re
import calendar
READS = ()
MONTHS = re.compile(r'\b(?:' + '|'.join(
    x for x in (*calendar.month_name, *calendar.month_abbr) if x) + r')\b', re.I)


def number_punctuation(text, token):
    match = re.search(r'\d+$', text)
    if not match:
        return -0.005
    number = match[0]
    n = len(number)
    before = text[:-n]
    char = before[-1:] or '\n'
    at_line_start = not before.split('\n')[-1].strip()
    year = n == 4 and 1500 <= int(number) <= 2099
    day = n <= 2 and 0 < int(number) <= 31 and MONTHS.search(before[-60:])
    decimal_count = len(re.findall(r'\d\.\d', before))
    comma_count = len(re.findall(r'\d,\d', before))
    # Was the most recent occurrence of THIS separator inside a number?
    i = before.rfind(token)
    group = re.match(r'\d+', before[i+1:]) if i > 0 else None
    joined_digits = bool(group and before[i-1].isdecimal())
    if token == '.':
        if joined_digits:
            if char == ',':
                return -1.8
            return -3.3 if int(number) == 0 else (-2.9 if n == 1 else -2.3)
        if n != 1:
            return 0.6 if year else -0.4
        if at_line_start:
            return -0.5
        if char == '.':
            return -0.4
        if int(number) == 0:
            return -2.6
        return -2.2 if decimal_count else -1.3
    if token == ',':
        if joined_digits and len(group[0]) >= 3:
            if char == '.':
                return -0.5
            if decimal_count >= 6:
                return -8.2
            return -5.5 if n == 1 else (-5.1 if n == 2 else -2.6)
        if day:
            return -3.4
        if n >= 4:
            return 0.4
        if char in '([{':
            return -2.0
        if char in '$€£¥₹':
            return -3.3
        if char.isspace():
            if comma_count:
                return -3.0
            return -1.5 if n <= 2 else -0.8
        return -0.9 if comma_count else -0.3
    if joined_digits:
        return -2.8 if char.isspace() else -1.6
    if day:
        return -2.5
    if n >= 3:
        return 0.3 if year else -0.1
    if n == 2:
        return -1.7 if char.isspace() else -1.1
    return -0.1 if char.isalpha() else -0.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    value = -0.005
    if token in ('.', ',', ':'):
        value = number_punctuation(text, token)
    elif text[-1:].isdecimal():
        if token in ('月', '월'):
            value = -1.3
        elif token in ('時', '时', '시'):
            value = -2.2
        elif token in ('点', '點'):
            value = -1.3
        elif token == '分':
            value = -2.7 if len(re.search(r'\d+$', text)[0]) == 1 else -1.4
        elif token == '/':
            value = -0.6 if len(re.search(r'\d+$', text)[0]) <= 2 else -0.005
    if previous.strip().lower() == 'because' and token == ' of':
        value = 1.4
    return (doc, (text + token)[-160:], token), float(value)

"""A mostly quiet detector of formatting boundaries.

Positive responses mark chat/tool headers and line breaks after short labels,
numbers or paths. Indentation and prose breaks are mostly quiet. Separate
negative cases are an opening 'Title:' label and repeated middle-dot filler.
The state holds document position, the preceding token, and a short line suffix.
"""
import re

READS = ()


def boundary_value(token, previous, line, position):
    word, label = previous.strip(), line.strip()
    if position == 1 and line == 'Title' and token == ':':
        return -14.865
    if token and set(token) == {'·'} and previous and set(previous) == {'·'}:
        return -1.163
    if position == 0:
        if token == '\xa0':
            return 2.47
        if token == '\n':
            return -0.49
        return -0.34 if token.strip().isalpha() else -0.10
    if '\n' in token:
        if token.isspace():
            if word in ('assistant', 'user', 'system', 'tool'):
                if position < 20:
                    return 1.238
                return 2.257 if word == 'assistant' else 2.127
            if word == '<tool_call>':
                return 3.03
            if word == '<tool_response>':
                return 2.56
            if word in ('<think>', '</think>'):
                return 1.0
            if word == '<|im_end|>':
                return 0.43
            if not label or token.count('\n') > 1:
                return 0.04
            if re.fullmatch(r'[+-]?\d+(?:[.,:]\d+)*', label):
                return 0.71
            if label.isalpha() or re.fullmatch(r'[\w.-]+', label):
                return 0.94
            if '/' in label and not any(c.isspace() for c in label):
                return 0.95
            if word.isalpha():
                return 0.0 if previous.startswith(' ') else 0.124
            return 0.15 if not word[-1:].isdigit() else 0.04
        if token.startswith(':'):
            if label == 'OBSERVATION':
                return 1.94
            return 0.34 if label.isalpha() else 0.0
        return 0.27 if token.startswith('/') else 0.0
    if token.isspace():
        if '\xa0' in token:
            return -0.42 if previous.startswith(' ') and word.isalpha() else 0.0
        if not label:
            return 0.0
        if '\t' in token:
            return -0.08
        if word == ']' and re.search(r'\[\d+\]$', label):
            return 0.62
        if word[-1:].isdigit():
            return 0.08
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, line = 0, '', ''
    else:
        _, position, previous, line = carry
    token = prefix.token_strings[-1]
    value = boundary_value(token, previous, line, position)
    line = (line + token).rsplit('\n', 1)[-1][-256:]
    return (document, position + 1, token, line), value

"""A coarse document-reset pulse, described by the first token's shape.

At a row/document start, predict a negative contribution: larger for
unspaced title-case words and digits, smaller for space-prefixed words.
Whitespace and control tokens have their own weak reset baselines.
Elsewhere predict only a small background. This deliberately leaves out
individual words' idiosyncratic activations.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    control = token.startswith('<|')
    reset = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])

    if not reset:
        if control:
            value = -0.012
        elif word.isdigit():
            value = 0.013
        elif not word:
            value = 0.001
        else:
            value = 0.0055
    elif control:
        value = -0.17
    elif not word:
        if '\n' in token or '\r' in token:
            value = -0.12
        else:
            value = 0.02 if len(token) == 1 else -0.50
    elif word.isdigit():
        value = -0.87
    elif word.isalpha():
        if token.startswith(' '):
            value = -0.35
        else:
            value = -0.93 if word.istitle() else -0.66
    else:
        value = -0.20 if token.startswith(' ') else -0.40
    return None, value

"""A sparse lexical response to speech, steps, and two Korean syllables.

Single-character Chinese/Japanese language and walking tokens give a
large negative response; a few short step compounds and Korean eo/si syllables
give weaker responses. Middle-dot and dash separators have small dips.
All other tokens are left at zero. These are token readings, not a claim
that the component recognizes a single shared meaning across languages.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '語':
        value = -3.2
    elif token == '语':
        value = -2.0
    elif token == '步':
        value = -3.3
    elif token == '歩':
        value = -2.5
    elif token == '一步':
        value = -2.5
    elif token in {'下一步', '起步', '进步', '同步'}:
        value = -1.8
    elif token == '第一步':
        value = -1.2
    elif token.strip() == '어':
        value = -1.2 if token.startswith(' ') else -1.9
    elif token.strip() == '시':
        value = -0.7 if token.startswith(' ') else -0.5
    elif token == '··':
        value = -0.61
    elif token == '–':
        value = -0.2
    else:
        value = 0.0
    return None, value

"""Approximate the component's checking/challenging/limiting word families.

Carry words across token splits; strengthen selected complement prepositions.
A separate negative rule looks for a token straddling a familiar word or German
stem, especially consonant-only pieces near German function words. These are
partial patterns, not a complete account of contextual activation. Also handle
the document-initial Title: marker and paired middle dots.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
CHECK = set('test check question doubt review explore scrutiny hint'.split())
RESTRAINT = set('restrain constrain curb hinder impede hamper stifle quash '
                'confound dismantle undermine weaken reconsider confront '
                'curtail suppress rescind contradict unleash hound haunt'.split())
LIMIT = set('constraint restriction limit stop halt end shape slow restrict'.split())
CONFLICT = set('threaten threat attack oppose reject reverse contest critique'.split())
# Each relation names a familiar grammatical/semantic construction.
COMPLEMENTS = {
    'to': (set('challenge threat contrary blow'.split()), 2.1),
    'about': (set('debate discussion argument question concern doubt'.split()), 1.1),
    'on': (set('constraint restriction limit pressure burden attack'.split()), 1.1),
    'into': (set('investigation research inquiry look insight'.split()), 1.1),
    'of': (set('critique criticism review test question'.split()), 0.8),
    'for': ({'evidence'}, 0.9),
}
ROOTS = CHECK | RESTRAINT | LIMIT | CONFLICT
for words, weight in COMPLEMENTS.values():
    ROOTS |= words
GERMAN = set('der die das und mit von nicht eine ist zu '
             'den des sich auf für dem'.split())
VOWELS = set('aeiouy')

@lru_cache(maxsize=30000)
def root(word):
    return next((w for w in wordnet.base_forms(word) if w in ROOTS), word)

@lru_cache(maxsize=30000)
def freq(word, language):
    return zipf_frequency(word.lower(), language)

@lru_cache(maxsize=20000)
def fragment(word, piece, german):
    if not (word and piece.isascii() and piece.isalpha()
            and 2 <= len(piece) <= 7):
        return 0.0
    joined = word + piece
    if freq(joined, 'en') > 2.5:
        return 0.0
    # Complete a word/stem strictly inside the new piece, before a consonant.
    completion = stem = 0.0
    for cut in range(1, len(piece)):
        before = word + piece[:cut]
        if piece[cut].lower() not in VOWELS:
            completion = max(completion, freq(before, 'en'), freq(before, 'de'))
            stem = max(stem, *(freq(before + e, 'de') for e in ('e', 'en')))
    consonants = not any(c in VOWELS for c in piece.lower())
    if consonants and word[-1].lower() not in VOWELS:
        if german and stem > 1.9:
            known = freq(joined, 'de')
            return -1.2 if known == 0 else (-0.4 if known < 2.5 else -0.1)
        if completion > 3.8 and freq(joined, 'en') == 0:
            return -0.5
    if german and completion > 5 and freq(joined, 'de') == 0:
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0.0)
    _, word, token, position, german = carry
    german *= 0.85
    if s[:1].isspace() and s.strip().lower() in GERMAN:
        german += 1.0
    match = re.search(r'[^\W\d_]+$', s)
    joined = (word + s if match.start() == 0 else match[0]) if match else ''
    low = joined.lower()
    base = root(low) if low.isascii() else ''
    value = 0.0
    if base == 'challenge':
        value = 2.1 if low.endswith('ed') else (1.1 if low.endswith('ing') else 1.4)
        if joined[:1].isupper():
            value *= 0.55
    elif base in RESTRAINT:
        value = 0.9
    elif base in CONFLICT | LIMIT:
        value = 0.2 if low == base else 0.4
        if base in {'constraint', 'constrain', 'threaten'}:
            value = 0.8
        if low == 'constraint':
            value = 0.25
        if low == 'end':
            value = 0.03
    elif base in CHECK:
        value = 0.2 if not low.endswith(('ed', 'ing')) else 0.6
        if base == 'question':
            if low.endswith(('ed', 'ing')):
                value = 1.0
            if word.lower() == 'to':
                value = 1.4
    if base == 'hint':
        value = 0.8
    if low == 'challeng':
        value = 2.4
    if s[:1].isspace() and low in COMPLEMENTS:
        words, weight = COMPLEMENTS[low]
        previous = root(word.lower())
        if previous in words:
            value = weight
            if (previous == 'challenge'
                    and word.lower() not in {'challenge', 'challenges'}):
                value = 0.0
    if value == 0.0:
        value = fragment(word, s, german > 0.001)
    if s in {'挑战', '挑戰'}:
        value = 0.75
    if position == 0 and s == 'Title':
        value = 0.6
    if position == 1 and token == 'Title' and s == ':':
        value = 3.0
    if s == '··':
        value = 0.57
    return (doc, joined[-40:], s, position + 1, german), float(value)
